@Test
public void testRefreshOnReadFailureAfterUnbuffer() throws Exception {
    // GIVEN
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    when(clientFactory.acquireClientForReadData(pipeline)).thenReturn(client);
    final int len = 200;
    final ChunkInputStream stream = mock(ChunkInputStream.class);
    when(stream.read(any(), anyInt(), anyInt())).thenThrow(new StorageContainerException("test", CONTAINER_NOT_FOUND)).thenReturn(len);
    when(stream.getRemaining()).thenReturn((long) len);
    when(refreshPipeline.apply(blockID)).thenReturn(newPipeline);
    BlockInputStream subject = new BlockInputStream(blockID, blockSize, pipeline, null, false, clientFactory, refreshPipeline) {

        @Override
        protected List<ChunkInfo> getChunkInfos() throws IOException {
            acquireClient();
            return chunks;
        }

        @Override
        protected ChunkInputStream createChunkInputStream(ChunkInfo chunkInfo) {
            return stream;
        }
    };
    try {
        subject.initialize();
        subject.unbuffer();
        // WHEN
        byte[] b = new byte[len];
        int bytesRead = subject.read(b, 0, len);
        // THEN
        Assert.assertEquals(len, bytesRead);
        verify(refreshPipeline).apply(blockID);
        verify(clientFactory).acquireClientForReadData(pipeline);
        verify(clientFactory).releaseClient(client, false);
    } finally {
        subject.close();
    }
}

@Test
public void test() throws IOException {
    final BufferPool bufferPool = new BufferPool(4 * 1024 * 1024, 32 / 4);
    for (int block = 0; block < 10; block++) {
        BlockOutputStream outputStream = createBlockOutputStream(bufferPool);
        Random random = new Random(SEED);
        int max = 256 * 1024 * 1024 / writeUnitSize;
        byte[] writeBuffer = new byte[writeUnitSize];
        for (int t = 0; t < max; t++) {
            if (writeUnitSize > 1) {
                for (int i = 0; i < writeBuffer.length; i++) {
                    writeBuffer[i] = (byte) random.nextInt();
                }
                outputStream.write(writeBuffer, 0, writeBuffer.length);
            } else {
                outputStream.write((byte) random.nextInt());
            }
        }
        outputStream.close();
    }
}

@Test
public void releaseAndReallocate() {
    BufferPool pool = new BufferPool(1024, 8);
    ChunkBuffer cb1 = pool.allocateBuffer(0);
    ChunkBuffer cb2 = pool.allocateBuffer(0);
    ChunkBuffer cb3 = pool.allocateBuffer(0);
    pool.releaseBuffer(cb1);
    //current state cb2, -> cb3, cb1
    final ChunkBuffer allocated = pool.allocateBuffer(0);
    Assert.assertEquals(3, pool.getSize());
    Assert.assertEquals(cb1, allocated);
}

