/**
 * This is a bit of a tricky test in the parametrized environment.
 * The goal is to ensure that the following methods do validation while
 * creating the ReplicationConfig: getDefault, adjustReplication, parse.
 *
 * Two other creator methods fromProtoTypeAndFactor, and fromTypeAndFactor
 * should allow creation of disallowed ReplicationConfigs as well, as in the
 * system there might exist some keys that were created with a now disallowed
 * ReplicationConfig.
 */
@Test
public void testValidationBasedOnConfig() {
    assumeRatisOrStandaloneType();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(OZONE_REPLICATION + ".allowed-configs", "^STANDALONE/ONE|RATIS/THREE$");
    conf.set(OZONE_REPLICATION, factor);
    conf.set(OZONE_REPLICATION_TYPE, type);
    // in case of allowed configurations
    if ((type.equals("RATIS") && factor.equals("THREE")) || (type.equals("STAND_ALONE") && factor.equals("ONE"))) {
        ReplicationConfig replicationConfig = ReplicationConfig.parse(org.apache.hadoop.hdds.client.ReplicationType.valueOf(type), factor, conf);
        // check if adjust throws exception when adjusting to a config that is
        // not allowed
        if (type.equals("RATIS")) {
            assertThrows(IllegalArgumentException.class, () -> ReplicationConfig.adjustReplication(replicationConfig, (short) 1, conf));
        } else {
            assertThrows(IllegalArgumentException.class, () -> ReplicationConfig.adjustReplication(replicationConfig, (short) 3, conf));
        }
        ReplicationConfig.getDefault(conf);
    } else {
        // parse should fail in case of a configuration that is not allowed.
        assertThrows(IllegalArgumentException.class, () -> ReplicationConfig.parse(org.apache.hadoop.hdds.client.ReplicationType.valueOf(type), factor, conf));
        // default can not be a configuration that is not allowed.
        assertThrows(IllegalArgumentException.class, () -> ReplicationConfig.getDefault(conf));
    }
    // From proto and java objects, we need to be able to create replication
    // configs even though they are not allowed, as there might have been
    // keys, that were created earlier when the config was allowed.
    ReplicationConfig.fromTypeAndFactor(org.apache.hadoop.hdds.client.ReplicationType.valueOf(type), org.apache.hadoop.hdds.client.ReplicationFactor.valueOf(factor));
    ReplicationConfig.fromProtoTypeAndFactor(ReplicationType.valueOf(type), ReplicationFactor.valueOf(factor));
    // CHAINED replication type is not supported by ReplicationConfig.
    assertThrows(RuntimeException.class, () -> ReplicationConfig.parse(org.apache.hadoop.hdds.client.ReplicationType.CHAINED, "", conf));
}

