@Test
public void testFeatureFinalization() throws Exception {
    LayoutFeature[] lfs = getTestLayoutFeatures(3);
    versionManager.init(1, lfs);
    versionManager.finalized(lfs[1]);
    assertEquals(3, versionManager.features.size());
