@Test
public void testCreateContainerWithWriteChunk() throws IOException {
    String testDir = GenericTestUtils.getTempPath(TestHddsDispatcher.class.getSimpleName());
    try {
        UUID scmId = UUID.randomUUID();
        OzoneConfiguration conf = new OzoneConfiguration();
        conf.set(HDDS_DATANODE_DIR_KEY, testDir);
        conf.set(OzoneConfigKeys.OZONE_METADATA_DIRS, testDir);
        DatanodeDetails dd = randomDatanodeDetails();
        HddsDispatcher hddsDispatcher = createDispatcher(dd, scmId, conf);
        ContainerCommandRequestProto writeChunkRequest = getWriteChunkRequest(dd.getUuidString(), 1L, 1L);
        // send read chunk request and make sure container does not exist
        ContainerCommandResponseProto response = hddsDispatcher.dispatch(getReadChunkRequest(writeChunkRequest), null);
        Assert.assertEquals(response.getResult(), ContainerProtos.Result.CONTAINER_NOT_FOUND);
        // send write chunk request without sending create container
        response = hddsDispatcher.dispatch(writeChunkRequest, null);
        // container should be created as part of write chunk request
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        // send read chunk request to read the chunk written above
        response = hddsDispatcher.dispatch(getReadChunkRequest(writeChunkRequest), null);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        ByteString responseData = BufferUtils.concatByteStrings(response.getReadChunk().getDataBuffers().getBuffersList());
        Assert.assertEquals(writeChunkRequest.getWriteChunk().getData(), responseData);
        // put block
        ContainerCommandRequestProto putBlockRequest = ContainerTestHelper.getPutBlockRequest(writeChunkRequest);
        response = hddsDispatcher.dispatch(putBlockRequest, null);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        // send list block request
        ContainerCommandRequestProto listBlockRequest = ContainerTestHelper.getListBlockRequest(writeChunkRequest);
        response = hddsDispatcher.dispatch(listBlockRequest, null);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertEquals(1, response.getListBlock().getBlockDataList().size());
        for (ContainerProtos.BlockData blockData : response.getListBlock().getBlockDataList()) {
            Assert.assertEquals(writeChunkRequest.getWriteChunk().getBlockID(), blockData.getBlockID());
            Assert.assertEquals(writeChunkRequest.getWriteChunk().getChunkData().getLen(), blockData.getSize());
            Assert.assertEquals(1, blockData.getChunksCount());
        }
    } finally {
        ContainerMetrics.remove();
        FileUtils.deleteDirectory(new File(testDir));
    }
}

