@Test(timeout = 30000)
public void testBlockThrottle() throws Exception {
    // Properties :
    //  - Number of containers : 5
    //  - Number of blocks per container : 3
    //  - Number of chunks per block : 1
    //  - Container limit per interval : 10
    //  - Block limit per container : 2
    //
    // Each time containers can be all scanned, but only 10 blocks
    // can be actually deleted. So it requires 2 waves
    // to cleanup all the 15 blocks.
    DatanodeConfiguration dnConf = conf.getObject(DatanodeConfiguration.class);
    dnConf.setBlockDeletionLimit(10);
    this.blockLimitPerInterval = dnConf.getBlockDeletionLimit();
    conf.setFromObject(dnConf);
    ContainerSet containerSet = new ContainerSet();
    ContainerMetrics metrics = ContainerMetrics.create(conf);
    KeyValueHandler keyValueHandler = new KeyValueHandler(conf, datanodeUuid, containerSet, volumeSet, metrics, c -> {
    });
    int containerCount = 5;
    int blocksPerContainer = 3;
    createToDeleteBlocks(containerSet, containerCount, blocksPerContainer, 1);
    BlockDeletingServiceTestImpl service = getBlockDeletingService(containerSet, conf, keyValueHandler);
    service.start();
    List<ContainerData> containerData = Lists.newArrayList();
    containerSet.listContainer(0L, containerCount, containerData);
    long blockSpace = containerData.get(0).getBytesUsed() / blocksPerContainer;
    long totalContainerSpace = containerCount * containerData.get(0).getBytesUsed();
    try {
        GenericTestUtils.waitFor(service::isStarted, 100, 3000);
        // Total blocks = 3 * 5 = 15
        // blockLimitPerInterval = 10
        // each interval will at most runDeletingTasks = 10 blocks
        // but as per of deletion policy (random/topNorder), it will fetch all 3
        // blocks from first 3 containers and 1 block from last container.
        // C1 - 3 BLOCKS, C2 - 3 BLOCKS, C3 - 3 BLOCKS, C4 - 1 BLOCK
        // Deleted space of 10 blocks should be equal to (initial total space
        // of container - current total space of container).
        deleteAndWait(service, 1);
        GenericTestUtils.waitFor(() -> blockLimitPerInterval * blockSpace == (totalContainerSpace - currentBlockSpace(containerData, containerCount)), 100, 3000);
        // There is only 5 blocks left to runDeletingTasks
        // (Deleted space of previous 10 blocks + these left 5 blocks) should
        // be equal to (initial total space of container
        // - current total space of container(it will be zero as all blocks
        // in all the containers are deleted)).
        deleteAndWait(service, 2);
        long totalContainerBlocks = blocksPerContainer * containerCount;
        GenericTestUtils.waitFor(() -> totalContainerBlocks * blockSpace == (totalContainerSpace - currentBlockSpace(containerData, containerCount)), 100, 3000);
    } finally {
        service.shutdown();
    }
}

@Test
public void testContainerCacheEviction() throws Exception {
    File root = new File(testRoot);
    root.mkdirs();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setInt(OzoneConfigKeys.OZONE_CONTAINER_CACHE_SIZE, 2);
    ContainerCache cache = ContainerCache.getInstance(conf);
    cache.clear();
    Assert.assertEquals(0, cache.size());
    File containerDir1 = new File(root, "cont1");
    File containerDir2 = new File(root, "cont2");
    File containerDir3 = new File(root, "cont3");
    File containerDir4 = new File(root, "cont4");
    createContainerDB(conf, containerDir1);
    createContainerDB(conf, containerDir2);
    createContainerDB(conf, containerDir3);
    createContainerDB(conf, containerDir4);
    ContainerCacheMetrics metrics = cache.getMetrics();
    long numDbGetCount = metrics.getNumDbGetOps();
    long numCacheMisses = metrics.getNumCacheMisses();
    // Get 2 references out of the same db and verify the objects are same.
    ReferenceCountedDB db1 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    Assert.assertEquals(1, db1.getReferenceCount());
    Assert.assertEquals(numDbGetCount + 1, metrics.getNumDbGetOps());
    ReferenceCountedDB db2 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    Assert.assertEquals(2, db2.getReferenceCount());
    Assert.assertEquals(numCacheMisses + 1, metrics.getNumCacheMisses());
    Assert.assertEquals(2, db1.getReferenceCount());
    Assert.assertEquals(db1, db2);
    Assert.assertEquals(numDbGetCount + 2, metrics.getNumDbGetOps());
    Assert.assertEquals(numCacheMisses + 1, metrics.getNumCacheMisses());
    // add one more references to ContainerCache.
    ReferenceCountedDB db3 = cache.getDB(2, "RocksDB", containerDir2.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    Assert.assertEquals(1, db3.getReferenceCount());
    // and close the reference
    db3.close();
    Assert.assertEquals(0, db3.getReferenceCount());
    // add one more reference to ContainerCache and verify that it will not
    // evict the least recent entry as it has reference.
    ReferenceCountedDB db4 = cache.getDB(3, "RocksDB", containerDir3.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    Assert.assertEquals(1, db4.getReferenceCount());
    Assert.assertEquals(2, cache.size());
    Assert.assertNotNull(cache.get(containerDir1.getPath()));
    Assert.assertNull(cache.get(containerDir2.getPath()));
    // Now close both the references for container1
    db1.close();
    db2.close();
    Assert.assertEquals(0, db1.getReferenceCount());
    Assert.assertEquals(0, db2.getReferenceCount());
    // The reference count for container1 is 0 but it is not evicted.
    ReferenceCountedDB db5 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    Assert.assertEquals(1, db5.getReferenceCount());
    Assert.assertEquals(db1, db5);
    db5.close();
    db4.close();
    // Decrementing reference count below zero should fail.
    thrown.expect(IllegalArgumentException.class);
    db5.close();
}

