public void testDatanodeStateMachineWithIdWriteFail() throws Exception {
    File idPath = new File(conf.get(ScmConfigKeys.OZONE_SCM_DATANODE_ID_DIR), OzoneConsts.OZONE_SCM_DATANODE_ID_FILE_DEFAULT);
    idPath.delete();
