/**
 * Test if different datanode is used for each download attempt.
 */
@Test(timeout = 10_000L)
public void testRandomSelection() throws ExecutionException, InterruptedException {
    //GIVEN
    final List<DatanodeDetails> datanodes = createDatanodes();
    SimpleContainerDownloader downloader = new SimpleContainerDownloader(new OzoneConfiguration(), null) {

        @Override
        protected CompletableFuture<Path> downloadContainer(long containerId, DatanodeDetails datanode) {
            //download is always successful.
            return CompletableFuture.completedFuture(Paths.get(datanode.getUuidString()));
        }
    };
    //WHEN executed, THEN at least once the second datanode should be
    //returned.
    for (int i = 0; i < 10000; i++) {
        Path path = downloader.getContainerDataFromReplicas(1L, datanodes);
        if (path.toString().equals(datanodes.get(1).getUuidString())) {
            return;
        }
    }
    //there is 1/3^10_000 chance for false positive, which is practically 0.
    Assert.fail("Datanodes are selected 10000 times but second datanode was never " + "used.");
}

