@Test
public void testTableCacheWithRenameKey() {
    // putting cache with same epoch and different keyNames
    for (int i = 0; i < 3; i++) {
        tableCache.put(new CacheKey<>(Integer.toString(i).concat("A")), new CacheValue<>(Optional.absent(), i));
        tableCache.put(new CacheKey<>(Integer.toString(i).concat("B")), new CacheValue<>(Optional.of(Integer.toString(i)), i));
    }
    // Epoch entries should be like (long, (key1, key2, ...))
    // (0, (0A, 0B))  (1, (1A, 1B))  (2, (2A, 1B))
    Assert.assertEquals(3, tableCache.getEpochEntries().size());
    Assert.assertEquals(2, tableCache.getEpochEntries().get(0L).size());
    // Cache should be like (key, (cacheValue, long))
    // (0A, (null, 0))   (0B, (0, 0))
    // (1A, (null, 1))   (1B, (0, 1))
    // (2A, (null, 2))   (2B, (0, 2))
    for (int i = 0; i < 3; i++) {
        Assert.assertNull(tableCache.get(new CacheKey<>(Integer.toString(i).concat("A"))).getCacheValue());
        Assert.assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i).concat("B"))).getCacheValue());
    }
    ArrayList<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    tableCache.evictCache(epochs);
    Assert.assertEquals(0, tableCache.getEpochEntries().size());
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        Assert.assertEquals(0, tableCache.size());
    } else {
        Assert.assertEquals(3, tableCache.size());
    }
}

@Test
public void testPartialTableCacheWithNotContinousEntries() throws Exception {
    int totalCount = 0;
    int insertedCount = 3000;
    int cleanupCount = 0;
    ArrayList<Long> epochs = new ArrayList();
    for (long i = 0; i < insertedCount; i += 2) {
        if (cleanupCount++ < 1000) {
            epochs.add(i);
        }
        tableCache.put(new CacheKey<>(Long.toString(i)), new CacheValue<>(Optional.of(Long.toString(i)), i));
        totalCount++;
    }
    Assert.assertEquals(totalCount, tableCache.size());
    tableCache.evictCache(epochs);
    final int count = totalCount;
    // If cleanup policy is manual entries should have been removed.
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        Assert.assertEquals(count - epochs.size(), tableCache.size());
        // Check remaining entries exist or not and deleted entries does not
        // exist.
        for (long i = 0; i < insertedCount; i += 2) {
            if (!epochs.contains(i)) {
                Assert.assertEquals(Long.toString(i), tableCache.get(new CacheKey<>(Long.toString(i))).getCacheValue());
            } else {
                Assert.assertEquals(null, tableCache.get(new CacheKey<>(Long.toString(i))));
            }
        }
    } else {
        for (long i = 0; i < insertedCount; i += 2) {
            Assert.assertEquals(Long.toString(i), tableCache.get(new CacheKey<>(Long.toString(i))).getCacheValue());
        }
    }
}

@Test
public void testPartialTableCacheWithOverrideEntries() throws Exception {
    tableCache.put(new CacheKey<>(Long.toString(0)), new CacheValue<>(Optional.of(Long.toString(0)), 0));
    tableCache.put(new CacheKey<>(Long.toString(1)), new CacheValue<>(Optional.of(Long.toString(1)), 1));
    tableCache.put(new CacheKey<>(Long.toString(2)), new CacheValue<>(Optional.of(Long.toString(2)), 2));
    //Override first 2 entries
    // This is to simulate a case like create mpu key, commit part1, commit
    // part2. They override the same key.
    tableCache.put(new CacheKey<>(Long.toString(0)), new CacheValue<>(Optional.of(Long.toString(0)), 3));
    tableCache.put(new CacheKey<>(Long.toString(1)), new CacheValue<>(Optional.of(Long.toString(1)), 4));
    Assert.assertEquals(3, tableCache.size());
    // It will have 2 additional entries because we have 2 override entries.
    Assert.assertEquals(3 + 2, tableCache.getEpochEntries().size());
    // Now remove
    List<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        Assert.assertEquals(0, tableCache.size());
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    }
    // Add a new entry.
    tableCache.put(new CacheKey<>(Long.toString(5)), new CacheValue<>(Optional.of(Long.toString(5)), 5));
    epochs = new ArrayList<>();
    epochs.add(5L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        Assert.assertEquals(0, tableCache.size());
        // Overrided entries would have been deleted.
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    }
}

@Test
public void testPartialTableCacheWithOverrideAndDelete() throws Exception {
    tableCache.put(new CacheKey<>(Long.toString(0)), new CacheValue<>(Optional.of(Long.toString(0)), 0));
    tableCache.put(new CacheKey<>(Long.toString(1)), new CacheValue<>(Optional.of(Long.toString(1)), 1));
    tableCache.put(new CacheKey<>(Long.toString(2)), new CacheValue<>(Optional.of(Long.toString(2)), 2));
    //Override entries
    tableCache.put(new CacheKey<>(Long.toString(0)), new CacheValue<>(Optional.of(Long.toString(0)), 3));
    tableCache.put(new CacheKey<>(Long.toString(1)), new CacheValue<>(Optional.of(Long.toString(1)), 4));
    // Finally mark them for deleted
    tableCache.put(new CacheKey<>(Long.toString(0)), new CacheValue<>(Optional.absent(), 5));
    tableCache.put(new CacheKey<>(Long.toString(1)), new CacheValue<>(Optional.absent(), 6));
    // So now our cache epoch entries looks like
    // 0-0, 1-1, 2-2, 0-3, 1-4, 0-5, 1-6
    // Cache looks like
    // 0-5, 1-6, 2-2
    Assert.assertEquals(3, tableCache.size());
    // It will have 4 additional entries because we have 4 override entries.
    Assert.assertEquals(3 + 4, tableCache.getEpochEntries().size());
    // Now remove
    List<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    epochs.add(5L);
    epochs.add(6L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        Assert.assertEquals(0, tableCache.size());
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        tableCache.evictCache(epochs);
        Assert.assertEquals(1, tableCache.size());
        // Epoch entries which are overrided also will be cleaned up.
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    }
    // Add a new entry, now old override entries will be cleaned up.
    tableCache.put(new CacheKey<>(Long.toString(3)), new CacheValue<>(Optional.of(Long.toString(3)), 7));
    epochs = new ArrayList<>();
    epochs.add(7L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        Assert.assertEquals(0, tableCache.size());
        // Epoch entries which are overrided now would have been deleted.
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        tableCache.evictCache(epochs);
        // 2 entries will be in cache, as 2 are not deleted.
        Assert.assertEquals(2, tableCache.size());
        // Epoch entries which are not marked for delete will also be cleaned up.
        // As they are override entries in full cache.
        Assert.assertEquals(0, tableCache.getEpochEntries().size());
    }
}

@Test
public void testPartialTableCacheParallel() throws Exception {
    int totalCount = 0;
    CompletableFuture<Integer> future = CompletableFuture.supplyAsync(() -> {
        try {
            return writeToCache(10, 1, 0);
        } catch (InterruptedException ex) {
            fail("writeToCache got interrupt exception");
        }
        return 0;
    });
    int value = future.get();
    Assert.assertEquals(10, value);
    totalCount += value;
    future = CompletableFuture.supplyAsync(() -> {
        try {
            return writeToCache(10, 11, 100);
        } catch (InterruptedException ex) {
            fail("writeToCache got interrupt exception");
        }
        return 0;
    });
    // Check we have first 10 entries in cache.
    for (int i = 1; i <= 10; i++) {
        Assert.assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i))).getCacheValue());
    }
    value = future.get();
    Assert.assertEquals(10, value);
    totalCount += value;
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        int deleted = 5;
        // cleanup first 5 entires
        ArrayList<Long> epochs = new ArrayList<>();
        epochs.add(1L);
        epochs.add(2L);
        epochs.add(3L);
        epochs.add(4L);
        epochs.add(5L);
        tableCache.evictCache(epochs);
        // We should totalCount - deleted entries in cache.
        final int tc = totalCount;
        Assert.assertEquals(tc - deleted, tableCache.size());
        // Check if we have remaining entries.
        for (int i = 6; i <= totalCount; i++) {
            Assert.assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i))).getCacheValue());
        }
        epochs = new ArrayList<>();
        for (long i = 6; i <= totalCount; i++) {
            epochs.add(i);
        }
        tableCache.evictCache(epochs);
        // Cleaned up all entries, so cache size should be zero.
        Assert.assertEquals(0, tableCache.size());
    } else {
        ArrayList<Long> epochs = new ArrayList<>();
        for (long i = 0; i <= totalCount; i++) {
            epochs.add(i);
        }
        tableCache.evictCache(epochs);
        Assert.assertEquals(totalCount, tableCache.size());
    }
}

