    nodeNum = 1;
    excludedNodes.clear();
    excludedNodes.add(datanodes.get(0));
    excludedNodes.add(datanodes.get(5));
    datanodeDetails = policy.chooseDatanodes(excludedNodes, null, nodeNum, 0, 15);
    Assert.assertEquals(nodeNum, datanodeDetails.size());
    Assert.assertTrue(cluster.isSameParent(datanodeDetails.get(0), excludedNodes.get(0)) || cluster.isSameParent(datanodeDetails.get(0), excludedNodes.get(1)));
