    containerManager.updateContainerState(cidArray[0], HddsProtos.LifeCycleEvent.FINALIZE);
    Assert.assertEquals(9, containerManager.getContainers(HddsProtos.LifeCycleState.OPEN).size());
    Assert.assertEquals(1, containerManager.getContainers(HddsProtos.LifeCycleState.CLOSING).size());
    containerManager.updateContainerState(cidArray[1], HddsProtos.LifeCycleEvent.FINALIZE);
    Assert.assertEquals(8, containerManager.getContainers(HddsProtos.LifeCycleState.OPEN).size());
    Assert.assertEquals(2, containerManager.getContainers(HddsProtos.LifeCycleState.CLOSING).size());
    containerManager.updateContainerState(cidArray[1], HddsProtos.LifeCycleEvent.QUASI_CLOSE);
    containerManager.updateContainerState(cidArray[2], HddsProtos.LifeCycleEvent.FINALIZE);
    containerManager.updateContainerState(cidArray[2], HddsProtos.LifeCycleEvent.CLOSE);
    Assert.assertEquals(7, containerManager.getContainerStateCount(HddsProtos.LifeCycleState.OPEN));
    Assert.assertEquals(1, containerManager.getContainerStateCount(HddsProtos.LifeCycleState.CLOSING));
    Assert.assertEquals(1, containerManager.getContainerStateCount(HddsProtos.LifeCycleState.QUASI_CLOSED));
    Assert.assertEquals(1, containerManager.getContainerStateCount(HddsProtos.LifeCycleState.CLOSED));
