@Test
public void openECContainerKeyAndBytesUsedUpdatedToMinimumOfAllReplicas() throws IOException {
    final ECReplicationConfig repConfig = new ECReplicationConfig(3, 2);
    final ContainerReportHandler reportHandler = new ContainerReportHandler(nodeManager, containerManager);
    Pipeline pipeline = pipelineManager.createPipeline(repConfig);
    Map<Integer, DatanodeDetails> dns = new HashMap<>();
    final Iterator<DatanodeDetails> nodeIterator = nodeManager.getNodes(NodeStatus.inServiceHealthy()).iterator();
    for (int i = 1; i <= repConfig.getRequiredNodes(); i++) {
        dns.put(i, nodeIterator.next());
    }
    final ContainerReplicaProto.State replicaState = ContainerReplicaProto.State.OPEN;
    final ContainerInfo containerOne = getECContainer(LifeCycleState.OPEN, pipeline.getId(), repConfig);
    containerStateManager.addContainer(containerOne.getProtobuf());
    // Container loaded, no replicas reported from DNs. Expect zeros for
    // usage values.
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Report from data index 2 - should not update stats
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, dns.get(2), 50L, 60L, 2), publisher);
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(0L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Report from replica 1, it should update
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, dns.get(1), 50L, 60L, 1), publisher);
    assertEquals(50L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(60L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Parity 1 report a greater value, but as the container is own the stats
    // should be the min value.
    // Report from replica 1, it should update
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, dns.get(4), 80L, 90L, 4), publisher);
    assertEquals(50L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(60L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Parity 2 reports a lesser value, so the stored values should update
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, dns.get(5), 40, 30, 5), publisher);
    assertEquals(40L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(30L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
    // Report from data index 3 - should not update stats even though it has
    // lesser values
    reportHandler.onMessage(getContainerReportFromDatanode(containerOne.containerID(), replicaState, dns.get(2), 10L, 10L, 2), publisher);
    assertEquals(40L, containerManager.getContainer(containerOne.containerID()).getUsedBytes());
    assertEquals(30L, containerManager.getContainer(containerOne.containerID()).getNumberOfKeys());
}

