/**
 * When a container is QUASI_CLOSED and we don't have quorum to force close
 * the container, the container should have all the replicas in QUASI_CLOSED
 * state, else ReplicationManager will take action.
 *
 * In this test case we make one of the replica unhealthy, replication manager
 * will send delete container command to the datanode which has the unhealthy
 * replica.
 */
@Test
public void testQuasiClosedContainerWithUnhealthyReplica() throws IOException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    container.setUsedBytes(100);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, State.QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, State.QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, State.QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    final int currentDeleteCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand);
    final int currentReplicateCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand);
    // All the QUASI_CLOSED replicas have same originNodeId, so the
    // container will not be closed. ReplicationManager should take no action.
    replicationManager.processAll();
    eventQueue.processAll(1000);
    Assert.assertEquals(0, datanodeCommandHandler.getInvocation());
    // Make the first replica unhealthy
    final ContainerReplica unhealthyReplica = getReplicas(id, State.UNHEALTHY, 1000L, originNodeId, replicaOne.getDatanodeDetails());
    containerStateManager.updateContainerReplica(id, unhealthyReplica);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    Assert.assertEquals(currentDeleteCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    Assert.assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.deleteContainerCommand, replicaOne.getDatanodeDetails()));
    Assert.assertEquals(currentDeleteCommandCount + 1, replicationManager.getMetrics().getNumDeletionCmdsSent());
    // Now we will delete the unhealthy replica from in-memory.
    containerStateManager.removeContainerReplica(id, replicaOne);
    final long currentBytesToReplicate = replicationManager.getMetrics().getNumReplicationBytesTotal();
    // The container is under replicated as unhealthy replica is removed
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // We should get replicate command
    Assert.assertEquals(currentReplicateCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    Assert.assertEquals(currentReplicateCommandCount + 1, replicationManager.getMetrics().getNumReplicationCmdsSent());
    Assert.assertEquals(currentBytesToReplicate + 100L, replicationManager.getMetrics().getNumReplicationBytesTotal());
    Assert.assertEquals(1, replicationManager.getInflightReplication().size());
    Assert.assertEquals(1, replicationManager.getMetrics().getInflightReplication());
    // We should have one under replicated and one quasi_closed_stuck
    ReplicationManagerReport report = replicationManager.getContainerReport();
    Assert.assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    // Now we add the missing replica back
    DatanodeDetails targetDn = replicationManager.getInflightReplication().get(id).get(0).getDatanode();
    final ContainerReplica replicatedReplicaOne = getReplicas(id, State.CLOSED, 1000L, originNodeId, targetDn);
    containerStateManager.updateContainerReplica(id, replicatedReplicaOne);
    final long currentReplicationCommandCompleted = replicationManager.getMetrics().getNumReplicationCmdsCompleted();
    final long currentBytesCompleted = replicationManager.getMetrics().getNumReplicationBytesCompleted();
    replicationManager.processAll();
    eventQueue.processAll(1000);
    Assert.assertEquals(0, replicationManager.getInflightReplication().size());
    Assert.assertEquals(0, replicationManager.getMetrics().getInflightReplication());
    Assert.assertEquals(currentReplicationCommandCompleted + 1, replicationManager.getMetrics().getNumReplicationCmdsCompleted());
    Assert.assertEquals(currentBytesCompleted + 100L, replicationManager.getMetrics().getNumReplicationBytesCompleted());
    report = replicationManager.getContainerReport();
    Assert.assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    Assert.assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
}

/**
