    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    Assert.assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    // Now we remove the replica according to inflight
    DatanodeDetails targetDn = replicationManager.getInflightDeletion().get(id).get(0).getDatanode();
    if (targetDn.equals(replicaOne.getDatanodeDetails())) {
