    for (String node : nodes) {
        conf.set(ConfUtils.addKeySuffixes(OZONE_SCM_ADDRESS_KEY, scmServiceId, node), "localhost");
    }
    conf.set(OZONE_SCM_RATIS_PORT_KEY, "10000");
    conf.set(OZONE_SCM_GRPC_PORT_KEY, "10001");
    conf.set(OZONE_SCM_BLOCK_CLIENT_PORT_KEY, "9896");
    conf.set(OZONE_SCM_CLIENT_PORT_KEY, "9897");
    conf.set(OZONE_SCM_DATANODE_PORT_KEY, "9898");
    conf.set(OZONE_SCM_SECURITY_SERVICE_PORT_KEY, "9899");
    SCMHANodeDetails scmhaNodeDetails = SCMHANodeDetails.loadSCMHAConfig(conf);
    Assert.assertEquals("10000", conf.get(OZONE_SCM_RATIS_PORT_KEY));
    Assert.assertEquals("10001", conf.get(OZONE_SCM_GRPC_PORT_KEY));
    InetSocketAddress clientAddress = NetUtils.createSocketAddr("0.0.0.0", 9897);
    InetSocketAddress blockAddress = NetUtils.createSocketAddr("0.0.0.0", 9896);
    InetSocketAddress datanodeAddress = NetUtils.createSocketAddr("0.0.0.0", 9898);
    Assert.assertEquals(clientAddress, scmhaNodeDetails.getLocalNodeDetails().getClientProtocolServerAddress());
    Assert.assertEquals(blockAddress, scmhaNodeDetails.getLocalNodeDetails().getBlockProtocolServerAddress());
    Assert.assertEquals(datanodeAddress, scmhaNodeDetails.getLocalNodeDetails().getDatanodeProtocolServerAddress());
    Assert.assertEquals(10000, scmhaNodeDetails.getLocalNodeDetails().getRatisPort());
    Assert.assertEquals(10001, scmhaNodeDetails.getLocalNodeDetails().getGrpcPort());
    for (SCMNodeDetails peer : scmhaNodeDetails.getPeerNodeDetails()) {
        Assert.assertEquals(clientAddress, peer.getClientProtocolServerAddress());
        Assert.assertEquals(blockAddress, peer.getBlockProtocolServerAddress());
        Assert.assertEquals(datanodeAddress, peer.getDatanodeProtocolServerAddress());
        Assert.assertEquals(10000, peer.getRatisPort());
        Assert.assertEquals(10001, peer.getGrpcPort());
    }
    // Security protocol address is not set in SCMHANode Details.
    // Check conf is properly set with expected port.
    Assert.assertEquals(NetUtils.createSocketAddr("0.0.0.0", 9899), HddsServerUtil.getScmSecurityInetAddress(conf));
}

