/**
 * Tests that node manager handles layout versions for newly registered nodes
 * correctly.
 *
 * @throws IOException
 * @throws InterruptedException
 * @throws TimeoutException
 */
@Test
public void testScmLayoutOnRegister() throws Exception {
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(ScmConfigKeys.OZONE_SCM_PIPELINE_CREATION_INTERVAL, 1, TimeUnit.DAYS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        Assert.assertTrue(scm.checkLeader());
        // Nodes with mismatched SLV cannot join the cluster.
        registerWithCapacity(nodeManager, LARGER_SLV_LAYOUT_PROTO, errorNodeNotPermitted);
        registerWithCapacity(nodeManager, SMALLER_MLV_SLV_LAYOUT_PROTO, errorNodeNotPermitted);
        registerWithCapacity(nodeManager, LARGER_MLV_SLV_LAYOUT_PROTO, errorNodeNotPermitted);
        // Nodes with mismatched MLV can join, but should not be allowed in
        // pipelines.
        DatanodeDetails badMlvNode1 = registerWithCapacity(nodeManager, SMALLER_MLV_LAYOUT_PROTO, success);
        DatanodeDetails badMlvNode2 = registerWithCapacity(nodeManager, SMALLER_MLV_LAYOUT_PROTO, success);
        // This node has correct MLV and SLV, so it can join and be used in
        // pipelines.
        DatanodeDetails goodNode = registerWithCapacity(nodeManager, CORRECT_LAYOUT_PROTO, success);
        Assert.assertEquals(3, nodeManager.getAllNodes().size());
        scm.exitSafeMode();
        // SCM should auto create a factor 1 pipeline for the one healthy node.
        // Still should not have enough healthy nodes for ratis 3 pipeline.
        assertPipelines(HddsProtos.ReplicationFactor.ONE, count -> count == 1, Collections.singletonList(goodNode));
        assertPipelines(HddsProtos.ReplicationFactor.THREE, count -> count == 0, new ArrayList<>());
        // Even when safemode exit or new node addition trigger pipeline
        // creation, they will fail with not enough healthy nodes for ratis 3
        // pipeline. Therefore we do not have to worry about this create call
        // failing due to datanodes reaching their maximum pipeline limit.
        assertPipelineCreationFailsWithNotEnoughNodes(1);
        // Heartbeat bad MLV nodes back to healthy.
        nodeManager.processHeartbeat(badMlvNode1, CORRECT_LAYOUT_PROTO);
        nodeManager.processHeartbeat(badMlvNode2, CORRECT_LAYOUT_PROTO);
        // After moving out of healthy readonly, pipeline creation should be
        // triggered.
        assertPipelines(HddsProtos.ReplicationFactor.ONE, count -> count == 3, Arrays.asList(badMlvNode1, badMlvNode2, goodNode));
        assertPipelines(HddsProtos.ReplicationFactor.THREE, count -> count >= 1, Arrays.asList(badMlvNode1, badMlvNode2, goodNode));
    }
}

