@Test
public void testProcessNodeReportCheckOneNode() throws IOException {
    UUID key = getFirstKey();
    List<StorageReportProto> reportList = new ArrayList<>();
    Set<StorageLocationReport> reportSet = testData.get(key);
    SCMNodeStorageStatMap map = new SCMNodeStorageStatMap(conf);
    map.insertNewDatanode(key, reportSet);
    Assert.assertTrue(map.isKnownDatanode(key));
    UUID storageId = UUID.randomUUID();
    String path = GenericTestUtils.getRandomizedTempPath().concat("/" + storageId);
    StorageLocationReport report = reportSet.iterator().next();
    long reportCapacity = report.getCapacity();
    long reportScmUsed = report.getScmUsed();
    long reportRemaining = report.getRemaining();
    StorageReportProto storageReport = HddsTestUtils.createStorageReport(storageId, path, reportCapacity, reportScmUsed, reportRemaining, null);
    StorageReportResult result = map.processNodeReport(key, HddsTestUtils.createNodeReport(Arrays.asList(storageReport), Collections.emptyList()));
    Assert.assertEquals(SCMNodeStorageStatMap.ReportStatus.ALL_IS_WELL, result.getStatus());
    StorageContainerDatanodeProtocolProtos.NodeReportProto.Builder nrb = NodeReportProto.newBuilder();
    StorageReportProto srb = reportSet.iterator().next().getProtoBufMessage();
    reportList.add(srb);
    result = map.processNodeReport(key, HddsTestUtils.createNodeReport(reportList, Collections.emptyList()));
    Assert.assertEquals(SCMNodeStorageStatMap.ReportStatus.ALL_IS_WELL, result.getStatus());
    reportList.add(HddsTestUtils.createStorageReport(UUID.randomUUID(), path, reportCapacity, reportCapacity, 0, null));
    result = map.processNodeReport(key, HddsTestUtils.createNodeReport(reportList, Collections.emptyList()));
    Assert.assertEquals(SCMNodeStorageStatMap.ReportStatus.STORAGE_OUT_OF_SPACE, result.getStatus());
    // Mark a disk failed
    StorageReportProto srb2 = StorageReportProto.newBuilder().setStorageUuid(UUID.randomUUID().toString()).setStorageLocation(srb.getStorageLocation()).setScmUsed(reportCapacity).setCapacity(reportCapacity).setRemaining(0).setFailed(true).build();
    reportList.add(srb2);
    nrb.addAllStorageReport(reportList);
    result = map.processNodeReport(key, nrb.addStorageReport(srb).build());
    Assert.assertEquals(SCMNodeStorageStatMap.ReportStatus.FAILED_AND_OUT_OF_SPACE_STORAGE, result.getStatus());
}

@Test
public void testProcessMultipleNodeReports() throws SCMException {
    SCMNodeStorageStatMap map = new SCMNodeStorageStatMap(conf);
    int counter = 1;
    // Insert all testData into the SCMNodeStorageStatMap Map.
    for (Map.Entry<UUID, Set<StorageLocationReport>> keyEntry : testData.entrySet()) {
        map.insertNewDatanode(keyEntry.getKey(), keyEntry.getValue());
    }
    Assert.assertEquals(DATANODE_COUNT * capacity, map.getTotalCapacity());
    Assert.assertEquals(DATANODE_COUNT * remaining, map.getTotalFreeSpace());
    Assert.assertEquals(DATANODE_COUNT * used, map.getTotalSpaceUsed());
    // upadate 1/4th of the datanode to be full
    for (Map.Entry<UUID, Set<StorageLocationReport>> keyEntry : testData.entrySet()) {
        Set<StorageLocationReport> reportSet = new HashSet<>();
        String path = GenericTestUtils.getTempPath(TestSCMNodeStorageStatMap.class.getSimpleName() + "-" + keyEntry.getKey().toString());
        StorageLocationReport.Builder builder = StorageLocationReport.newBuilder();
        builder.setStorageType(StorageType.DISK).setId(keyEntry.getKey().toString()).setStorageLocation(path).setScmUsed(capacity).setRemaining(0).setCapacity(capacity).setFailed(false);
        reportSet.add(builder.build());
        map.updateDatanodeMap(keyEntry.getKey(), reportSet);
        counter++;
        if (counter > DATANODE_COUNT / 4) {
            break;
        }
    }
    Assert.assertEquals(DATANODE_COUNT / 4, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.CRITICAL).size());
    Assert.assertEquals(0, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.WARN).size());
    Assert.assertEquals(0.75 * DATANODE_COUNT, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.NORMAL).size(), 0);
    Assert.assertEquals(DATANODE_COUNT * capacity, map.getTotalCapacity(), 0);
    Assert.assertEquals(0.75 * DATANODE_COUNT * remaining, map.getTotalFreeSpace(), 0);
    Assert.assertEquals(0.75 * DATANODE_COUNT * used + (0.25 * DATANODE_COUNT * capacity), map.getTotalSpaceUsed(), 0);
    counter = 1;
    // Remove 1/4 of the DataNodes from the Map
    for (Map.Entry<UUID, Set<StorageLocationReport>> keyEntry : testData.entrySet()) {
        map.removeDatanode(keyEntry.getKey());
        counter++;
        if (counter > DATANODE_COUNT / 4) {
            break;
        }
    }
    Assert.assertEquals(0, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.CRITICAL).size());
    Assert.assertEquals(0, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.WARN).size());
    Assert.assertEquals(0.75 * DATANODE_COUNT, map.getDatanodeList(SCMNodeStorageStatMap.UtilizationThreshold.NORMAL).size(), 0);
    Assert.assertEquals(0.75 * DATANODE_COUNT * capacity, map.getTotalCapacity(), 0);
    Assert.assertEquals(0.75 * DATANODE_COUNT * remaining, map.getTotalFreeSpace(), 0);
    Assert.assertEquals(0.75 * DATANODE_COUNT * used, map.getTotalSpaceUsed(), 0);
}

