@Test
public void testUpdatePipelineStates() throws Exception {
    SCMHADBTransactionBuffer buffer = new SCMHADBTransactionBufferStub(dbStore);
    PipelineManagerImpl pipelineManager = createPipelineManager(true, buffer);
    Table<PipelineID, Pipeline> pipelineStore = SCMDBDefinition.PIPELINES.getTable(dbStore);
    Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
    Assert.assertEquals(1, pipelineManager.getPipelines().size());
    Assert.assertTrue(pipelineManager.containsPipeline(pipeline.getId()));
    Assert.assertEquals(ALLOCATED, pipeline.getPipelineState());
    buffer.flush();
    Assert.assertEquals(ALLOCATED, pipelineStore.get(pipeline.getId()).getPipelineState());
    PipelineID pipelineID = pipeline.getId();
    pipelineManager.openPipeline(pipelineID);
    pipelineManager.addContainerToPipeline(pipelineID, ContainerID.valueOf(1));
    Assert.assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).contains(pipeline));
    buffer.flush();
    Assert.assertTrue(pipelineStore.get(pipeline.getId()).isOpen());
    pipelineManager.deactivatePipeline(pipeline.getId());
    Assert.assertEquals(Pipeline.PipelineState.DORMANT, pipelineManager.getPipeline(pipelineID).getPipelineState());
    buffer.flush();
    Assert.assertEquals(Pipeline.PipelineState.DORMANT, pipelineStore.get(pipeline.getId()).getPipelineState());
    Assert.assertFalse(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).contains(pipeline));
    Assert.assertEquals(1, pipelineManager.getPipelineCount(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.DORMANT));
    pipelineManager.activatePipeline(pipeline.getId());
    Assert.assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).contains(pipeline));
    Assert.assertEquals(1, pipelineManager.getPipelineCount(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN));
    buffer.flush();
    Assert.assertTrue(pipelineStore.get(pipeline.getId()).isOpen());
    pipelineManager.close();
}

