public void testPickLowestLoadAnchor() throws IOException {
    List<DatanodeDetails> healthyNodes = nodeManager.getNodes(NodeStatus.inServiceHealthy());
    int maxPipelineCount = PIPELINE_LOAD_LIMIT * healthyNodes.size() / HddsProtos.ReplicationFactor.THREE.getNumber();
    for (int i = 0; i < maxPipelineCount; i++) {
        try {
            List<DatanodeDetails> nodes = placementPolicy.chooseDatanodes(null, null, HddsProtos.ReplicationFactor.THREE.getNumber(), 0, 0);
