@Test
public void testCreatePipelinesDnExclude() throws Exception {
    int maxPipelinePerNode = 2;
    init(maxPipelinePerNode);
    List<DatanodeDetails> healthyNodes = nodeManager.getNodes(NodeStatus.inServiceHealthy());
    Assume.assumeTrue(healthyNodes.size() == 8);
    HddsProtos.ReplicationFactor factor = HddsProtos.ReplicationFactor.THREE;
    // Use up first 3 DNs for an open pipeline.
    List<DatanodeDetails> dns = healthyNodes.subList(0, 3);
    for (int i = 0; i < maxPipelinePerNode; i++) {
        // Saturate pipeline counts on all the 1st 3 DNs.
        addPipeline(dns, Pipeline.PipelineState.OPEN, RatisReplicationConfig.getInstance(factor));
    }
    Set<DatanodeDetails> membersOfOpenPipelines = new HashSet<>(dns);
    // Use up next 3 DNs for a closed pipeline.
    dns = healthyNodes.subList(3, 6);
    addPipeline(dns, Pipeline.PipelineState.CLOSED, RatisReplicationConfig.getInstance(factor));
    Set<DatanodeDetails> membersOfClosedPipelines = new HashSet<>(dns);
    // only 2 healthy DNs left that are not part of any pipeline
    Pipeline pipeline = provider.create(RatisReplicationConfig.getInstance(factor));
    assertPipelineProperties(pipeline, factor, REPLICATION_TYPE, Pipeline.PipelineState.ALLOCATED);
    HddsProtos.Pipeline pipelineProto = pipeline.getProtobufMessage(ClientVersion.CURRENT_VERSION);
    nodeManager.addPipeline(pipeline);
    stateManager.addPipeline(pipelineProto);
    List<DatanodeDetails> nodes = pipeline.getNodes();
    assertTrue("nodes of new pipeline cannot be all from open pipelines", nodes.stream().noneMatch(membersOfOpenPipelines::contains));
    assertTrue("at least 1 node should have been from members of closed pipelines", nodes.stream().anyMatch(membersOfClosedPipelines::contains));
    cleanup();
}

