@Test
public void testClientUpdateWithDelayedRevoke() throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    SCMUpdateServiceGrpcServer server = new SCMUpdateServiceGrpcServer(getUpdateServiceConfig(conf), mockCRLStore);
    ClientCRLStore clientCRLStore = new ClientCRLStore();
    // check pending crl every 5 seconds
    SCMUpdateClientConfiguration updateClientConfiguration = conf.getObject(SCMUpdateClientConfiguration.class);
    updateClientConfiguration.setClientCrlCheckInterval(Duration.ofSeconds(2));
    conf.setFromObject(updateClientConfiguration);
    SCMUpdateServiceGrpcClient client = new SCMUpdateServiceGrpcClient("localhost", conf, clientCRLStore);
    server.start();
    client.start();
    try {
        // issue 10 certs
        List<BigInteger> certIds = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            BigInteger certId = mockCRLStore.issueCert();
            certIds.add(certId);
        }
        // revoke cert 0
        revokeCertNow((certIds.get(0)));
        server.notifyCrlUpdate();
        GenericTestUtils.waitFor(() -> client.getUpdateCount() == 1, 100, 2000);
        Assert.assertEquals(1, client.getUpdateCount());
        Assert.assertEquals(0, client.getErrorCount());
        // revoke cert 5 with 10 seconds delay
        revokeCert(certIds.get(5), Instant.now().plus(Duration.ofSeconds(5)));
        server.notifyCrlUpdate();
        GenericTestUtils.waitFor(() -> client.getUpdateCount() > 1, 100, 2000);
        Assert.assertTrue(2 <= client.getUpdateCount());
        Assert.assertEquals(0, client.getErrorCount());
        Assert.assertTrue(1 >= client.getClientCRLStore().getPendingCrlIds().size());
        GenericTestUtils.waitFor(() -> client.getPendingCrlRemoveCount() == 1, 100, 20_000);
        Assert.assertTrue(client.getClientCRLStore().getPendingCrlIds().isEmpty());
    } catch (Exception e) {
        e.printStackTrace();
    } finally {
        client.stop(true);
        server.stop();
    }
}

@Ignore("HDDS-5319")
@Test
public void testClientUpdateWithRestart() throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    SCMUpdateServiceGrpcServer server = new SCMUpdateServiceGrpcServer(getUpdateServiceConfig(conf), mockCRLStore);
    ClientCRLStore clientCRLStore = new ClientCRLStore();
    SCMUpdateServiceGrpcClient client = new SCMUpdateServiceGrpcClient("localhost", conf, clientCRLStore);
    server.start();
    client.start();
    try {
        // issue 10 certs
        List<BigInteger> certIds = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            BigInteger certId = mockCRLStore.issueCert();
            certIds.add(certId);
        }
        // revoke 4 certs and broadcast
        for (int i = 0; i < 4; i++) {
            revokeCertNow((certIds.get(i)));
        }
        server.notifyCrlUpdate();
        GenericTestUtils.waitFor(() -> client.getUpdateCount() == 4, 100, 2000);
        Assert.assertEquals(4, client.getUpdateCount());
        // server restart
        // client onError->
        // 1. reconnect
        // 2. new subscribe resumes from previous state
        LOG.info("Test server restart begin.");
        // server shutdown can lead to duplicate message received on client when
        // client retry connect to the server. The client will handle that.
        server.stop();
        server.start();
        GenericTestUtils.waitFor(() -> client.getErrorCount() == 1, 100, 2000);
        Assert.assertEquals(4, client.getUpdateCount());
        Assert.assertEquals(1, client.getErrorCount());
        Assert.assertEquals(4, clientCRLStore.getLatestCrlId());
        LOG.info("Test server restart end.");
        revokeCertNow(certIds.get(5));
        server.notifyCrlUpdate();
        GenericTestUtils.waitFor(() -> client.getUpdateCount() > 4, 100, 5000);
        Assert.assertEquals(5, client.getUpdateCount());
        Assert.assertEquals(1, client.getErrorCount());
        Assert.assertEquals(5, clientCRLStore.getLatestCrlId());
        // client restart
        // server onError->
        // 1. remove stale client
        // 2. new subscribe resumes from previous state.
        LOG.info("Test client restart begin.");
        // a full client channel shutdown and create
        client.stop(true);
        client.createChannel();
        client.start();
        Assert.assertEquals(5, clientCRLStore.getLatestCrlId());
        GenericTestUtils.waitFor(() -> client.getUpdateCount() > 5, 100, 2000);
        revokeCertNow(certIds.get(6));
        // mostly noop
        server.notifyCrlUpdate();
        LOG.info("Test client restart end.");
        GenericTestUtils.waitFor(() -> client.getUpdateCount() > 6, 100, 2000);
        Assert.assertTrue(client.getUpdateCount() >= 6);
        Assert.assertEquals(2, client.getErrorCount());
        Assert.assertEquals(6, clientCRLStore.getLatestCrlId());
    } catch (Exception e) {
        e.printStackTrace();
    } finally {
        client.stop(true);
        server.stop();
    }
}

@Test
public void testUpgrade() throws Exception {
    // Write version file for original version.
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setInt(ScmConfig.ConfigStrings.HDDS_SCM_INIT_DEFAULT_LAYOUT_VERSION, HDDSLayoutFeature.INITIAL_VERSION.layoutVersion());
    conf.setBoolean(ScmConfigKeys.OZONE_SCM_HA_ENABLE_KEY, haEnabledBefore);
    conf.set(ScmConfigKeys.OZONE_SCM_DB_DIRS, dataPath);
    conf.set(OzoneConfigKeys.OZONE_METADATA_DIRS, dataPath);
    // This init should always succeed, since SCM is not pre-finalized yet.
    boolean initResult1 = StorageContainerManager.scmInit(conf, CLUSTER_ID);
    Assert.assertTrue(initResult1);
    // Set up new pre-finalized SCM.
    conf.setBoolean(ScmConfigKeys.OZONE_SCM_HA_ENABLE_KEY, haEnabledPreFinalized);
    StorageContainerManager scm = HddsTestUtils.getScm(conf);
    Assert.assertEquals(UpgradeFinalizer.Status.FINALIZATION_REQUIRED, scm.getUpgradeFinalizer().getStatus());
    if (shouldFail) {
        // Start on its own should fail.
        LambdaTestUtils.intercept(UpgradeException.class, scm::start);
        // Init followed by start should both fail.
        // Init is not necessary here, but is allowed to be run.
        LambdaTestUtils.intercept(UpgradeException.class, () -> StorageContainerManager.scmInit(conf, CLUSTER_ID));
        LambdaTestUtils.intercept(UpgradeException.class, scm::start);
    } else {
        boolean initResult2 = StorageContainerManager.scmInit(conf, CLUSTER_ID);
        Assert.assertTrue(initResult2);
        scm.start();
        scm.stop();
    }
}

@Test
public void testStartupSlvLessThanMlv() throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    File scmSubdir = tempFolder.newFolder("scm", "current");
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(ScmConfigKeys.OZONE_SCM_DB_DIRS, tempFolder.getRoot().getAbsolutePath());
    // Set metadata layout version larger then software layout version.
    int largestSlv = 0;
    for (LayoutFeature f : HDDSLayoutFeature.values()) {
        largestSlv = Math.max(largestSlv, f.layoutVersion());
    }
    int mlv = largestSlv + 1;
    // Create version file with MLV > SLV, which should fail the SCM
    // construction.
    UpgradeTestUtils.createVersionFile(scmSubdir, HddsProtos.NodeType.SCM, mlv);
    try {
        new StorageContainerManager(conf);
        Assert.fail("Expected IOException due to incorrect MLV on SCM creation.");
    } catch (IOException e) {
        String expectedMessage = String.format("Metadata layout version (%s) > " + "software layout version (%s)", mlv, largestSlv);
        GenericTestUtils.assertExceptionContains(expectedMessage, e);
    }
}

