@Test
public void testComputeMd5Crc() throws IOException {
    final int lenOfZeroBytes = 32;
    byte[] emptyChunkChecksum = new byte[lenOfZeroBytes];
    MD5Hash emptyBlockMD5 = MD5Hash.digest(emptyChunkChecksum);
    byte[] emptyBlockMD5Hash = emptyBlockMD5.getDigest();
    ByteString checkSum = ByteString.copyFrom(emptyChunkChecksum);
    ContainerProtos.ChecksumData checksumData = ContainerProtos.ChecksumData.newBuilder().addChecksums(checkSum).setBytesPerChecksum(4).setType(ContainerProtos.ChecksumType.CRC32).build();
    ContainerProtos.ChunkInfo chunkInfo = ContainerProtos.ChunkInfo.newBuilder().setChecksumData(checksumData).setChunkName("dummy_chunk").setOffset(0).setLen(lenOfZeroBytes).build();
    List<ContainerProtos.ChunkInfo> chunkInfoList = Collections.singletonList(chunkInfo);
    AbstractBlockChecksumComputer computer = new ReplicatedBlockChecksumComputer(chunkInfoList);
    computer.compute();
    ByteBuffer output = computer.getOutByteBuffer();
    assertArrayEquals(emptyBlockMD5Hash, output.array());
}

