        long localId = blockList.getKeyLocationsList().get(i).getBlockID().getContainerBlockID().getLocalID();
        Assert.assertEquals(i + 1, localId);
    }
    Assert.assertEquals(1, transportStub.getKeys().get(volumeName).get(bucketName).get("mykey").getKeyLocationListCount());
