                Assert.fail("listStatus() Failed");
                return false;
            }
        }, 1000, 120000);
    }
    FileStatus[] fileStatuses = fs.listStatus(parent);
    // the number of immediate children of root is 1
    Assert.assertEquals(1, fileStatuses.length);
    writeClient.deleteKey(keyArgs);
}

