    long numBlockAllocationsOrg = cluster.getOzoneManager().getMetrics().getNumBlockAllocates();
    try (FSDataOutputStream out1 = fs.create(file, FsPermission.getDefault(), true, 8, (short) 3, 1, null)) {
        for (int i = 0; i < 100000; i++) {
