@Test
public void testCreateKeyShouldUseRefreshedBucketReplicationConfig() throws IOException {
    OzoneBucket bucket = TestDataUtil.createVolumeAndBucket(cluster, bucketLayout);
    final TestClock testClock = new TestClock(Instant.now(), ZoneOffset.UTC);
    String rootPath = String.format("%s://%s.%s/", OzoneConsts.OZONE_URI_SCHEME, bucket.getName(), bucket.getVolumeName());
    // Set the fs.defaultFS and start the filesystem
    Configuration conf = new OzoneConfiguration(cluster.getConf());
    conf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    // Set the number of keys to be processed during batch operate.
    OzoneFileSystem o3FS = (OzoneFileSystem) FileSystem.get(conf);
    //Let's reset the clock to control the time.
    ((BasicOzoneClientAdapterImpl) (o3FS.getAdapter())).setClock(testClock);
    createKeyAndAssertKeyType(bucket, o3FS, new Path(rootPath, "key"), ReplicationType.RATIS);
    bucket.setReplicationConfig(new ECReplicationConfig("rs-3-2-1024k"));
    //After changing the bucket policy, it should create ec key, but o3fs will
    // refresh after some time. So, it will be sill old type.
    createKeyAndAssertKeyType(bucket, o3FS, new Path(rootPath, "key1"), ReplicationType.RATIS);
    testClock.fastForward(300 * 1000 + 1);
    //After client bucket refresh time, it should create new type what is
    // available on bucket at that moment.
    createKeyAndAssertKeyType(bucket, o3FS, new Path(rootPath, "key2"), ReplicationType.EC);
    // Rechecking the same steps with changing to Ratis again to check the
    // behavior is consistent.
    bucket.setReplicationConfig(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE));
    createKeyAndAssertKeyType(bucket, o3FS, new Path(rootPath, "key3"), ReplicationType.EC);
    testClock.fastForward(300 * 1000 + 1);
    createKeyAndAssertKeyType(bucket, o3FS, new Path(rootPath, "key4"), ReplicationType.RATIS);
}

