@Test
public void testLoopInLinkBuckets() throws Exception {
    String linksVolume = UUID.randomUUID().toString();
    OzoneClient client = cluster.getClient();
    ObjectStore store = client.getObjectStore();
    // Create volume
    store.createVolume(linksVolume);
    OzoneVolume volume = store.getVolume(linksVolume);
    String linkBucket1Name = UUID.randomUUID().toString();
    String linkBucket2Name = UUID.randomUUID().toString();
    String linkBucket3Name = UUID.randomUUID().toString();
    // case-1: Create a loop in the link buckets
    createLinkBucket(volume, linkBucket1Name, linkBucket2Name);
    createLinkBucket(volume, linkBucket2Name, linkBucket3Name);
    createLinkBucket(volume, linkBucket3Name, linkBucket1Name);
    // Set the fs.defaultFS and start the filesystem
    String rootPath = String.format("%s://%s.%s/", OzoneConsts.OZONE_URI_SCHEME, linkBucket1Name, linksVolume);
    conf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    try {
        FileSystem.get(conf);
        Assert.fail("Should throw Exception due to loop in Link Buckets");
    } catch (OMException oe) {
        // Expected exception
        Assert.assertEquals(OMException.ResultCodes.DETECTED_LOOP_IN_BUCKET_LINKS, oe.getResult());
    }
    // case-2: Dangling link bucket
    String danglingLinkBucketName = UUID.randomUUID().toString();
    String sourceBucketName = UUID.randomUUID().toString();
    // danglingLinkBucket is a dangling link over a source bucket that doesn't
    // exist.
    createLinkBucket(volume, sourceBucketName, danglingLinkBucketName);
    rootPath = String.format("%s://%s.%s/", OzoneConsts.OZONE_URI_SCHEME, danglingLinkBucketName, linksVolume);
    conf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    try {
        FileSystem.get(conf);
        Assert.fail("Should throw Exception due to loop in Link Buckets");
    } catch (OMException oe) {
        // Expected exception
        Assert.assertEquals(OMException.ResultCodes.BUCKET_NOT_FOUND, oe.getResult());
    }
}

/**
 * Test OM HA URLs with qualified fs.defaultFS.
 * @throws Exception
 */
@Test
public void testWithQualifiedDefaultFS() throws Exception {
    OzoneConfiguration clientConf = new OzoneConfiguration(conf);
    clientConf.setQuietMode(false);
    clientConf.set(o3fsImplKey, o3fsImplValue);
    // fs.defaultFS = o3fs://bucketName.volumeName.omServiceId/
    clientConf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    // Pick leader OM's RPC address and assign it to ozone.om.address for
    // the test case: ozone fs -ls o3fs://bucket.volume.om1/
    String leaderOMNodeAddr = getLeaderOMNodeAddr();
    // ozone.om.address was set to service id in MiniOzoneHAClusterImpl
    clientConf.set(OMConfigKeys.OZONE_OM_ADDRESS_KEY, leaderOMNodeAddr);
    FsShell shell = new FsShell(clientConf);
    int res;
    try {
        // Test case 1: ozone fs -ls /
        // Expectation: Success.
        res = ToolRunner.run(shell, new String[] { "-ls", "/" });
        // Check return value, should be 0 (success)
        Assert.assertEquals(0, res);
        // Test case 2: ozone fs -ls o3fs:///
        // Expectation: Success. fs.defaultFS is a fully qualified path.
        res = ToolRunner.run(shell, new String[] { "-ls", "o3fs:///" });
        Assert.assertEquals(0, res);
        // Test case 3: ozone fs -ls o3fs://bucket.volume/
        // Expectation: Fail. Must have service id or host name when HA is enabled
        String unqualifiedPath1 = String.format("%s://%s.%s/", OzoneConsts.OZONE_URI_SCHEME, bucketName, volumeName);
        try (GenericTestUtils.SystemErrCapturer capture = new GenericTestUtils.SystemErrCapturer()) {
            res = ToolRunner.run(shell, new String[] { "-ls", unqualifiedPath1 });
            // Check stderr, inspired by testDFSWithInvalidCommmand
            Assert.assertThat("Command did not print the error message " + "correctly for test case: ozone fs -ls o3fs://bucket.volume/", capture.getOutput(), StringContains.containsString("-ls: Service ID or host name must not" + " be omitted when ozone.om.service.ids is defined."));
        }
        // Check return value, should be -1 (failure)
        Assert.assertEquals(res, -1);
        // Test case 4: ozone fs -ls o3fs://bucket.volume.om1/
        // Expectation: Success. The client should use the port number
        // set in ozone.om.address.
        String qualifiedPath1 = String.format("%s://%s.%s.%s/", OzoneConsts.OZONE_URI_SCHEME, bucketName, volumeName, getHostFromAddress(leaderOMNodeAddr));
        res = ToolRunner.run(shell, new String[] { "-ls", qualifiedPath1 });
        // Note: this test case will fail if the port is not from the leader node
        Assert.assertEquals(0, res);
        // Test case 5: ozone fs -ls o3fs://bucket.volume.om1:port/
        // Expectation: Success.
        String qualifiedPath2 = String.format("%s://%s.%s.%s/", OzoneConsts.OZONE_URI_SCHEME, bucketName, volumeName, leaderOMNodeAddr);
        res = ToolRunner.run(shell, new String[] { "-ls", qualifiedPath2 });
        Assert.assertEquals(0, res);
        // Test case 6: ozone fs -ls o3fs://bucket.volume.id1/
        // Expectation: Success.
        String qualifiedPath3 = String.format("%s://%s.%s.%s/", OzoneConsts.OZONE_URI_SCHEME, bucketName, volumeName, omServiceId);
        res = ToolRunner.run(shell, new String[] { "-ls", qualifiedPath3 });
        Assert.assertEquals(0, res);
        // Test case 7: ozone fs -ls o3fs://bucket.volume.id1:port/
        // Expectation: Fail. Service ID does not use port information.
        // Use the port number from leader OM (doesn't really matter)
        String unqualifiedPath2 = String.format("%s://%s.%s.%s:%d/", OzoneConsts.OZONE_URI_SCHEME, bucketName, volumeName, omServiceId, getPortFromAddress(leaderOMNodeAddr));
        try (GenericTestUtils.SystemErrCapturer capture = new GenericTestUtils.SystemErrCapturer()) {
            res = ToolRunner.run(shell, new String[] { "-ls", unqualifiedPath2 });
            // Check stderr
            Assert.assertThat("Command did not print the error message " + "correctly for test case: " + "ozone fs -ls o3fs://bucket.volume.id1:port/", capture.getOutput(), StringContains.containsString("does not use port information"));
        }
        // Check return value, should be -1 (failure)
        Assert.assertEquals(res, -1);
    } finally {
        shell.close();
    }
}

