@Test
public void testUpdateContainerState() throws IOException, InvalidStateTransitionException {
    Set<ContainerID> containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.OPEN);
    int containers = containerList == null ? 0 : containerList.size();
    Assert.assertEquals(0, containers);
    // Allocate container1 and update its state from
    // OPEN -> CLOSING -> CLOSED -> DELETING -> DELETED
    ContainerWithPipeline container1 = scm.getClientProtocolServer().allocateContainer(SCMTestUtils.getReplicationType(conf), SCMTestUtils.getReplicationFactor(conf), OzoneConsts.OZONE);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.OPEN);
    Assert.assertEquals(1, containerList.size());
    containerManager.updateContainerState(container1.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.FINALIZE);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.CLOSING);
    Assert.assertEquals(1, containerList.size());
    containerManager.updateContainerState(container1.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.CLOSE);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.CLOSED);
    Assert.assertEquals(1, containerList.size());
    containerManager.updateContainerState(container1.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.DELETE);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.DELETING);
    Assert.assertEquals(1, containerList.size());
    containerManager.updateContainerState(container1.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.CLEANUP);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.DELETED);
    Assert.assertEquals(1, containerList.size());
    // Allocate container1 and update its state from
    // OPEN -> CLOSING -> CLOSED
    ContainerWithPipeline container3 = scm.getClientProtocolServer().allocateContainer(SCMTestUtils.getReplicationType(conf), SCMTestUtils.getReplicationFactor(conf), OzoneConsts.OZONE);
    containerManager.updateContainerState(container3.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.FINALIZE);
    containerManager.updateContainerState(container3.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.CLOSE);
    containerManager.updateContainerState(container1.getContainerInfo().containerID(), HddsProtos.LifeCycleEvent.CLOSE);
    containerList = containerStateManager.getContainerIDs(HddsProtos.LifeCycleState.CLOSED);
    Assert.assertEquals(1, containerList.size());
}

@Test
public void testReplicaMap() throws Exception {
    DatanodeDetails dn1 = DatanodeDetails.newBuilder().setHostName("host1").setIpAddress("1.1.1.1").setUuid(UUID.randomUUID()).build();
    DatanodeDetails dn2 = DatanodeDetails.newBuilder().setHostName("host2").setIpAddress("2.2.2.2").setUuid(UUID.randomUUID()).build();
    // Test 1: no replica's exist
    ContainerID containerID = ContainerID.valueOf(RandomUtils.nextLong());
    Set<ContainerReplica> replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertNull(replicaSet);
    ContainerWithPipeline container = scm.getClientProtocolServer().allocateContainer(SCMTestUtils.getReplicationType(conf), SCMTestUtils.getReplicationFactor(conf), OzoneConsts.OZONE);
    ContainerID id = container.getContainerInfo().containerID();
    // Test 2: Add replica nodes and then test
    ContainerReplica replicaOne = ContainerReplica.newBuilder().setContainerID(id).setContainerState(ContainerReplicaProto.State.OPEN).setDatanodeDetails(dn1).build();
    ContainerReplica replicaTwo = ContainerReplica.newBuilder().setContainerID(id).setContainerState(ContainerReplicaProto.State.OPEN).setDatanodeDetails(dn2).build();
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    replicaSet = containerStateManager.getContainerReplicas(id);
    Assert.assertEquals(2, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(replicaOne));
    Assert.assertTrue(replicaSet.contains(replicaTwo));
    // Test 3: Remove one replica node and then test
    containerStateManager.removeContainerReplica(id, replicaOne);
    replicaSet = containerStateManager.getContainerReplicas(id);
    Assert.assertEquals(1, replicaSet.size());
    Assert.assertFalse(replicaSet.contains(replicaOne));
    Assert.assertTrue(replicaSet.contains(replicaTwo));
    // Test 3: Remove second replica node and then test
    containerStateManager.removeContainerReplica(id, replicaTwo);
    replicaSet = containerStateManager.getContainerReplicas(id);
    Assert.assertEquals(0, replicaSet.size());
    Assert.assertFalse(replicaSet.contains(replicaOne));
    Assert.assertFalse(replicaSet.contains(replicaTwo));
    // Test 4: Re-insert dn1
    containerStateManager.updateContainerReplica(id, replicaOne);
    replicaSet = containerStateManager.getContainerReplicas(id);
    Assert.assertEquals(1, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(replicaOne));
    Assert.assertFalse(replicaSet.contains(replicaTwo));
    // Re-insert dn2
    containerStateManager.updateContainerReplica(id, replicaTwo);
    replicaSet = containerStateManager.getContainerReplicas(id);
    Assert.assertEquals(2, replicaSet.size());
