@Test
public void testECContainerKeysCount() throws IOException, InterruptedException, TimeoutException {
    byte[] inputData = getInputBytes(1);
    final OzoneBucket bucket = getOzoneBucket();
    ContainerOperationClient containerOperationClient = new ContainerOperationClient(conf);
    ECReplicationConfig repConfig = new ECReplicationConfig(3, 2, ECReplicationConfig.EcCodec.RS, chunkSize);
    // Close all EC pipelines so we must get a fresh pipeline and hence
    // container for this test.
    PipelineManager pm = cluster.getStorageContainerManager().getPipelineManager();
    for (Pipeline p : pm.getPipelines(repConfig)) {
        pm.closePipeline(p, true);
    }
    String keyName = UUID.randomUUID().toString();
    try (OzoneOutputStream out = bucket.createKey(keyName, 4096, repConfig, new HashMap<>())) {
        out.write(inputData);
    }
    OzoneKeyDetails key = bucket.getKey(keyName);
    long currentKeyContainerID = key.getOzoneKeyLocations().get(0).getContainerID();
    GenericTestUtils.waitFor(() -> {
        try {
            return containerOperationClient.getContainer(currentKeyContainerID).getNumberOfKeys() == 1;
        } catch (IOException exception) {
            Assert.fail("Unexpected exception " + exception);
            return false;
        }
    }, 100, 10000);
    validateContent(inputData, bucket, key);
}

@Test
public void testWriteShouldSucceedWhenDNKilled() throws Exception {
    int numChunks = 3;
    byte[] inputData = getInputBytes(numChunks);
    final OzoneBucket bucket = getOzoneBucket();
    String keyName = "testWriteShouldSucceedWhenDNKilled" + numChunks;
    DatanodeDetails nodeToKill = null;
    try {
        try (OzoneOutputStream out = bucket.createKey(keyName, 1024, new ECReplicationConfig(3, 2, ECReplicationConfig.EcCodec.RS, chunkSize), new HashMap<>())) {
            out.write(inputData);
            // Kill a node from first pipeline
            nodeToKill = ((ECKeyOutputStream) out.getOutputStream()).getStreamEntries().get(0).getPipeline().getFirstNode();
            cluster.shutdownHddsDatanode(nodeToKill);
            out.write(inputData);
            // Check the second blockGroup pipeline to make sure that the failed not
            // is not selected.
            Assert.assertFalse(((ECKeyOutputStream) out.getOutputStream()).getStreamEntries().get(1).getPipeline().getNodes().contains(nodeToKill));
        }
        try (OzoneInputStream is = bucket.readKey(keyName)) {
            // We wrote "inputData" twice, so do two reads and ensure the correct
            // data comes back.
            for (int i = 0; i < 2; i++) {
                byte[] fileContent = new byte[inputData.length];
                Assert.assertEquals(inputData.length, is.read(fileContent));
                Assert.assertEquals(new String(inputData, UTF_8), new String(fileContent, UTF_8));
            }
        }
    } finally {
        cluster.restartHddsDatanode(nodeToKill, true);
    }
}

