        });
    });
    cluster.shutdownHddsDatanode(0);
    scm.getReplicationManager().processAll();
    ((EventQueue) scm.getEventQueue()).processAll(1000);
    containerInfos = scm.getContainerManager().getContainers();
    containerInfos.stream().forEach(container -> Assert.assertEquals(HddsProtos.LifeCycleState.DELETING, container.getState()));
    LogCapturer logCapturer = LogCapturer.captureLogs(LegacyReplicationManager.LOG);
    logCapturer.clearOutput();
    scm.getReplicationManager().processAll();
    ((EventQueue) scm.getEventQueue()).processAll(1000);
    GenericTestUtils.waitFor(() -> logCapturer.getOutput().contains("Resend delete Container"), 500, 3000);
    cluster.restartHddsDatanode(0, true);
    Thread.sleep(1000);
    scm.getReplicationManager().processAll();
    ((EventQueue) scm.getEventQueue()).processAll(1000);
    GenericTestUtils.waitFor(() -> {
        List<ContainerInfo> infos = scm.getContainerManager().getContainers();
        try {
            infos.stream().forEach(container -> {
                Assert.assertEquals(HddsProtos.LifeCycleState.DELETED, container.getState());
                try {
                    Assert.assertTrue(scm.getScmMetadataStore().getContainerTable().get(container.containerID()).getState() == HddsProtos.LifeCycleState.DELETED);
                } catch (IOException e) {
                    Assert.fail("Container from SCM DB should be marked as DELETED");
                }
            });
        } catch (Throwable e) {
            return false;
        }
        return true;
    }, 500, 5000);
    LOG.info(metrics.toString());
}

@Test
public void testBlockDeleteCommandParallelProcess() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = RandomStringUtils.random(64 * 1024);
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    int keyCount = 10;
    List<String> keys = new ArrayList<>();
    for (int j = 0; j < keyCount; j++) {
        String keyName = UUID.randomUUID().toString();
        OzoneOutputStream out = bucket.createKey(keyName, value.getBytes(UTF_8).length, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
        out.write(value.getBytes(UTF_8));
        out.close();
        keys.add(keyName);
    }
    // close the containers which hold the blocks for the key
    OzoneTestUtils.closeAllContainers(scm.getEventQueue(), scm);
    Thread.sleep(2000);
    for (int j = 0; j < keyCount; j++) {
        OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(keys.get(j)).setDataSize(0).setReplicationConfig(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE)).setRefreshPipeline(true).build();
        writeClient.deleteKey(keyArgs);
    }
    // Wait for block delete command sent from OM
    GenericTestUtils.waitFor(() -> {
        try {
            if (scm.getScmBlockManager().getDeletedBlockLog().getNumOfValidTransactions() > 0) {
                return true;
            }
        } catch (IOException e) {
        }
        return false;
    }, 100, 5000);
    long start = System.currentTimeMillis();
    // Wait for all blocks been deleted.
    GenericTestUtils.waitFor(() -> {
        try {
            if (scm.getScmBlockManager().getDeletedBlockLog().getNumOfValidTransactions() == 0) {
                return true;
            }
        } catch (IOException e) {
        }
        return false;
    }, 100, 30000);
    long end = System.currentTimeMillis();
    System.out.println("Block deletion costs " + (end - start) + "ms");
}

