                if (hasToken) {
                    Instant expiryDate = tokenExpired ? Instant.now().minusSeconds(3600) : Instant.now().plusSeconds(3600);
                    ContainerTokenIdentifier tokenIdentifier = new ContainerTokenIdentifier(user, containerID, caClient.getCertificate().getSerialNumber().toString(), expiryDate);
                    token = secretManager.generateToken(tokenIdentifier);
