/**
 * Tests the following scenarios:
 * 1. Bootstrap without updating config on any existing OM -> fail
 * 2. Force bootstrap without upating config on any OM -> fail
 */
@Test
@Flaky("HDDS-6077")
public void testBootstrapWithoutConfigUpdate() throws Exception {
    // Setup 1 node cluster
    setupCluster(1);
    cluster.setupExitManagerForTesting();
    OzoneManager existingOM = cluster.getOzoneManager(0);
    String existingOMNodeId = existingOM.getOMNodeId();
    GenericTestUtils.LogCapturer omLog = GenericTestUtils.LogCapturer.captureLogs(OzoneManager.LOG);
    GenericTestUtils.LogCapturer miniOzoneClusterLog = GenericTestUtils.LogCapturer.captureLogs(MiniOzoneHAClusterImpl.LOG);
    /**
     * ************************************************************************
     *  1. Bootstrap without updating config on any existing OM -> fail
     * ************************************************************************
     */
    // Bootstrap a new node without updating the configs on existing OMs.
    // This should result in the bootstrap failing.
    String newNodeId = "omNode-bootstrap-1";
    try {
        cluster.bootstrapOzoneManager(newNodeId, false, false);
        Assert.fail("Bootstrap should have failed as configs are not updated on" + " all OMs.");
    } catch (Exception e) {
        Assert.assertEquals(OmUtils.getOMAddressListPrintString(Lists.newArrayList(existingOM.getNodeDetails())) + " do not have or" + " have incorrect information of the bootstrapping OM. Update their " + "ozone-site.xml before proceeding.", e.getMessage());
        Assert.assertTrue(omLog.getOutput().contains("Remote OM config check " + "failed on OM " + existingOMNodeId));
        Assert.assertTrue(miniOzoneClusterLog.getOutput().contains(newNodeId + " - System Exit"));
    }
    /**
     * ************************************************************************
     *  2. Force bootstrap without updating config on any OM -> fail
     * ************************************************************************
     */
    // Force Bootstrap a new node without updating the configs on existing OMs.
    // This should avoid the bootstrap check but the bootstrap should fail
    // eventually as the SetConfiguration request cannot succeed.
    miniOzoneClusterLog.clearOutput();
    omLog.clearOutput();
    newNodeId = "omNode-bootstrap-2";
    try {
        cluster.bootstrapOzoneManager(newNodeId, false, true);
        Assert.fail();
    } catch (IOException e) {
        Assert.assertTrue(omLog.getOutput().contains("Couldn't add OM " + newNodeId + " to peer list."));
        Assert.assertTrue(miniOzoneClusterLog.getOutput().contains(existingOMNodeId + " - System Exit: There is no OM configuration " + "for node ID " + newNodeId + " in ozone-site.xml."));
        // Verify that the existing OM has stopped.
        Assert.assertFalse(cluster.getOzoneManager(existingOMNodeId).isRunning());
    }
}

