    String followerNodeId = leaderOM.getPeerNodes().get(0).getNodeId();
    if (cluster.isOMActive(followerNodeId)) {
        followerNodeId = leaderOM.getPeerNodes().get(1).getNodeId();
    }
    OzoneManager followerOM = cluster.getOzoneManager(followerNodeId);
    // Do some transactions so that the log index increases
    List<String> keys = writeKeysToIncreaseLogIndex(leaderRatisServer, 200);
    // Get transaction Index
    TransactionInfo transactionInfo = TransactionInfo.readTransactionInfo(leaderOM.getMetadataManager());
    TermIndex leaderOMTermIndex = TermIndex.valueOf(transactionInfo.getTerm(), transactionInfo.getTransactionIndex());
    long leaderOMSnapshotIndex = leaderOMTermIndex.getIndex();
    long leaderOMSnapshotTermIndex = leaderOMTermIndex.getTerm();
    // Start the inactive OM. Checkpoint installation will happen spontaneously.
    cluster.startInactiveOM(followerNodeId);
    GenericTestUtils.LogCapturer logCapture = GenericTestUtils.LogCapturer.captureLogs(OzoneManager.LOG);
    // Continuously read keys
    ExecutorService executor = Executors.newFixedThreadPool(1);
    Future<Void> readFuture = executor.submit(() -> {
        try {
            getKeys(keys, 10);
            readKeys(keys);
        } catch (IOException e) {
            Fail.fail("Read Key failed", e);
        }
        return null;
    });
    readFuture.get();
    // The recently started OM should be lagging behind the leader OM.
    // Wait & for follower to update transactions to leader snapshot index.
    // Timeout error if follower does not load update within 3s
    GenericTestUtils.waitFor(() -> {
        return followerOM.getOmRatisServer().getLastAppliedTermIndex().getIndex() >= leaderOMSnapshotIndex - 1;
    }, 100, 3000);
    long followerOMLastAppliedIndex = followerOM.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    assertTrue(followerOMLastAppliedIndex >= leaderOMSnapshotIndex - 1);
    // After the new checkpoint is installed, the follower OM
    // lastAppliedIndex must >= the snapshot index of the checkpoint. It
    // could be great than snapshot index if there is any conf entry from ratis.
    followerOMLastAppliedIndex = followerOM.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    assertTrue(followerOMLastAppliedIndex >= leaderOMSnapshotIndex);
    assertTrue(followerOM.getOmRatisServer().getLastAppliedTermIndex().getTerm() >= leaderOMSnapshotTermIndex);
    // Verify that the follower OM's DB contains the transactions which were
    // made while it was inactive.
    OMMetadataManager followerOMMetaMngr = followerOM.getMetadataManager();
    Assert.assertNotNull(followerOMMetaMngr.getVolumeTable().get(followerOMMetaMngr.getVolumeKey(volumeName)));
    Assert.assertNotNull(followerOMMetaMngr.getBucketTable().get(followerOMMetaMngr.getBucketKey(volumeName, bucketName)));
    for (String key : keys) {
        Assert.assertNotNull(followerOMMetaMngr.getKeyTable(getDefaultBucketLayout()).get(followerOMMetaMngr.getOzoneKey(volumeName, bucketName, key)));
    }
    // Wait installation finish
    Thread.sleep(5000);
    // Verify checkpoint installation was happened.
    Assert.assertTrue(logCapture.getOutput().contains("Reloaded OM state"));
    Assert.assertTrue(logCapture.getOutput().contains("Install Checkpoint is finished"));
}

@Test
public void testInstallOldCheckpointFailure() throws Exception {
    // Get the leader OM
    String leaderOMNodeId = OmFailoverProxyUtil.getFailoverProxyProvider(objectStore.getClientProxy()).getCurrentProxyOMNodeId();
    OzoneManager leaderOM = cluster.getOzoneManager(leaderOMNodeId);
    // Find the inactive OM and start it
    String followerNodeId = leaderOM.getPeerNodes().get(0).getNodeId();
    if (cluster.isOMActive(followerNodeId)) {
        followerNodeId = leaderOM.getPeerNodes().get(1).getNodeId();
    }
    cluster.startInactiveOM(followerNodeId);
    GenericTestUtils.setLogLevel(OzoneManager.LOG, Level.INFO);
    GenericTestUtils.LogCapturer logCapture = GenericTestUtils.LogCapturer.captureLogs(OzoneManager.LOG);
    OzoneManager followerOM = cluster.getOzoneManager(followerNodeId);
    OzoneManagerRatisServer followerRatisServer = followerOM.getOmRatisServer();
    // Do some transactions so that the log index increases on follower OM
    writeKeysToIncreaseLogIndex(followerRatisServer, 100);
    TermIndex leaderCheckpointTermIndex = leaderOM.getOmRatisServer().getLastAppliedTermIndex();
    DBCheckpoint leaderDbCheckpoint = leaderOM.getMetadataManager().getStore().getCheckpoint(false);
    // Do some more transactions to increase the log index further on
    // follower OM such that it is more than the checkpoint index taken on
    // leader OM.
    writeKeysToIncreaseLogIndex(followerOM.getOmRatisServer(), leaderCheckpointTermIndex.getIndex() + 100);
    // Install the old checkpoint on the follower OM. This should fail as the
    // followerOM is already ahead of that transactionLogIndex and the OM
    // state should be reloaded.
    TermIndex followerTermIndex = followerRatisServer.getLastAppliedTermIndex();
    TermIndex newTermIndex = followerOM.installCheckpoint(leaderOMNodeId, leaderDbCheckpoint);
    String errorMsg = "Cannot proceed with InstallSnapshot as OM is at " + "TermIndex " + followerTermIndex + " and checkpoint has lower " + "TermIndex";
    Assert.assertTrue(logCapture.getOutput().contains(errorMsg));
    Assert.assertNull("OM installed checkpoint even though checkpoint " + "logIndex is less than it's lastAppliedIndex", newTermIndex);
    Assert.assertEquals(followerTermIndex, followerRatisServer.getLastAppliedTermIndex());
    String msg = "OM DB is not stopped. Started services with Term: " + followerTermIndex.getTerm() + " and Index: " + followerTermIndex.getIndex();
    Assert.assertTrue(logCapture.getOutput().contains(msg));
}

@Test
public void testInstallCorruptedCheckpointFailure() throws Exception {
    // Get the leader OM
    String leaderOMNodeId = OmFailoverProxyUtil.getFailoverProxyProvider(objectStore.getClientProxy()).getCurrentProxyOMNodeId();
    OzoneManager leaderOM = cluster.getOzoneManager(leaderOMNodeId);
    OzoneManagerRatisServer leaderRatisServer = leaderOM.getOmRatisServer();
    // Find the inactive OM
    String followerNodeId = leaderOM.getPeerNodes().get(0).getNodeId();
    if (cluster.isOMActive(followerNodeId)) {
        followerNodeId = leaderOM.getPeerNodes().get(1).getNodeId();
    }
    OzoneManager followerOM = cluster.getOzoneManager(followerNodeId);
    // Do some transactions so that the log index increases
    writeKeysToIncreaseLogIndex(leaderRatisServer, 100);
    DBCheckpoint leaderDbCheckpoint = leaderOM.getMetadataManager().getStore().getCheckpoint(false);
    Path leaderCheckpointLocation = leaderDbCheckpoint.getCheckpointLocation();
    TransactionInfo leaderCheckpointTrxnInfo = OzoneManagerRatisUtils.getTrxnInfoFromCheckpoint(conf, leaderCheckpointLocation);
    // Corrupt the leader checkpoint and install that on the OM. The
    // operation should fail and OM should shutdown.
    boolean delete = true;
    for (File file : leaderCheckpointLocation.toFile().listFiles()) {
        if (file.getName().contains(".sst")) {
            if (delete) {
                file.delete();
                delete = false;
            } else {
                delete = true;
            }
        }
    }
    GenericTestUtils.setLogLevel(OzoneManager.LOG, Level.INFO);
    GenericTestUtils.LogCapturer logCapture = GenericTestUtils.LogCapturer.captureLogs(OzoneManager.LOG);
    followerOM.setExitManagerForTesting(new DummyExitManager());
    // Install corrupted checkpoint
    followerOM.installCheckpoint(leaderOMNodeId, leaderCheckpointLocation, leaderCheckpointTrxnInfo);
    // Wait checkpoint installation to be finished.
    GenericTestUtils.waitFor(() -> {
        Assert.assertTrue(logCapture.getOutput().contains("System Exit: " + "Failed to reload OM state and instantiate services."));
        return true;
    }, 100, 3000);
    String msg = "RPC server is stopped";
    Assert.assertTrue(logCapture.getOutput().contains(msg));
}

@Test
public void testStartupSlvLessThanMlv() throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    File omSubdir = tempFolder.newFolder("om", "current");
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(OMConfigKeys.OZONE_OM_DB_DIRS, tempFolder.getRoot().getAbsolutePath());
    // Set metadata layout version larger then software layout version.
    int largestSlv = 0;
    for (LayoutFeature f : OMLayoutFeature.values()) {
        largestSlv = Math.max(largestSlv, f.layoutVersion());
    }
    int mlv = largestSlv + 1;
    // Create version file with MLV > SLV, which should fail the cluster build.
    UpgradeTestUtils.createVersionFile(omSubdir, HddsProtos.NodeType.OM, mlv);
    MiniOzoneCluster.Builder clusterBuilder = MiniOzoneCluster.newBuilder(conf).setClusterId(UUID.randomUUID().toString()).setScmId(UUID.randomUUID().toString()).setOmId(UUID.randomUUID().toString());
    try {
        clusterBuilder.build();
        Assert.fail("Expected OMException due to incorrect MLV on OM creation.");
    } catch (OMException e) {
        String expectedMessage = String.format("Cannot initialize " + "VersionManager. Metadata layout version (%s) > software layout" + " version (%s)", mlv, largestSlv);
        GenericTestUtils.assertExceptionContains(expectedMessage, e);
    }
}

@Test
public void testRestartWithFSOLayout() throws Exception {
    try {
        // 1. build cluster with default bucket layout FSO
        OzoneConfiguration conf = new OzoneConfiguration();
        conf.set(OMConfigKeys.OZONE_DEFAULT_BUCKET_LAYOUT, BucketLayout.FILE_SYSTEM_OPTIMIZED.name());
        startCluster(conf);
        // 2. create bucket with FSO bucket layout and verify
        OzoneBucket bucket1 = TestDataUtil.createVolumeAndBucket(cluster, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        // 3. verify OM default behavior with LEGACY
        restartCluster();
        OzoneBucket bucket2 = TestDataUtil.createVolumeAndBucket(cluster, BucketLayout.LEGACY);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        // 4. create bucket with OBS bucket layout and verify
        restartCluster();
        OzoneBucket bucket3 = TestDataUtil.createVolumeAndBucket(cluster, BucketLayout.OBJECT_STORE);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
        // 5. verify all bucket
        restartCluster();
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
        // 6. verify after update default bucket layout
        conf.set(OMConfigKeys.OZONE_DEFAULT_BUCKET_LAYOUT, BucketLayout.OBJECT_STORE.name());
        restartCluster();
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
    } finally {
        teardown();
    }
}

