    }
    // close container
    PipelineManager manager = cluster.getStorageContainerManager().getPipelineManager();
    List<Pipeline> pipelines = manager.getPipelines().stream().filter(p -> RatisReplicationConfig.hasFactor(p.getReplicationConfig(), ReplicationFactor.THREE)).collect(Collectors.toList());
    Pipeline targetPipeline = pipelines.get(0);
    List<DatanodeDetails> nodes = targetPipeline.getNodes();
