@Test
public void testContainerRandomPort() throws IOException {
    OzoneConfiguration ozoneConf = SCMTestUtils.getConf();
    File testDir = PathUtils.getTestDir(TestOzoneContainer.class);
    ozoneConf.set(DFSConfigKeysLegacy.DFS_DATANODE_DATA_DIR_KEY, testDir.getAbsolutePath());
    ozoneConf.set(HddsConfigKeys.OZONE_METADATA_DIRS, TEST_ROOT.toString());
    // Each instance of SM will create an ozone container
    // that bounds to a random port.
    ozoneConf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_IPC_RANDOM_PORT, true);
    ozoneConf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_RATIS_IPC_RANDOM_PORT, true);
    List<DatanodeStateMachine> stateMachines = new ArrayList<>();
    try {
        for (int i = 0; i < 3; i++) {
            stateMachines.add(new DatanodeStateMachine(randomDatanodeDetails(), ozoneConf, null, null, null));
        }
        //we need to start all the servers to get the fix ports
        for (DatanodeStateMachine dsm : stateMachines) {
            dsm.getContainer().getReadChannel().start();
            dsm.getContainer().getWriteChannel().start();
        }
        for (DatanodeStateMachine dsm : stateMachines) {
            dsm.getContainer().getWriteChannel().stop();
            dsm.getContainer().getReadChannel().stop();
        }
        //after the start the real port numbers should be available AND unique
        HashSet<Integer> ports = new HashSet<Integer>();
        for (DatanodeStateMachine dsm : stateMachines) {
            int readPort = dsm.getContainer().getReadChannel().getIPCPort();
            assertNotEquals("Port number of the service is not updated", 0, readPort);
            assertTrue("Port of datanode service is conflicted with other server.", ports.add(readPort));
            int writePort = dsm.getContainer().getWriteChannel().getIPCPort();
            assertNotEquals("Port number of the service is not updated", 0, writePort);
            assertTrue("Port of datanode service is conflicted with other server.", ports.add(writePort));
        }
    } finally {
        for (DatanodeStateMachine dsm : stateMachines) {
            dsm.close();
        }
    }
    // Turn off the random port flag and test again
    ozoneConf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_IPC_RANDOM_PORT, false);
    try (DatanodeStateMachine sm1 = new DatanodeStateMachine(randomDatanodeDetails(), ozoneConf, null, null, null);
        DatanodeStateMachine sm2 = new DatanodeStateMachine(randomDatanodeDetails(), ozoneConf, null, null, null);
        DatanodeStateMachine sm3 = new DatanodeStateMachine(randomDatanodeDetails(), ozoneConf, null, null, null)) {
        HashSet<Integer> ports = new HashSet<Integer>();
        assertTrue(ports.add(sm1.getContainer().getReadChannel().getIPCPort()));
        assertFalse(ports.add(sm2.getContainer().getReadChannel().getIPCPort()));
        assertFalse(ports.add(sm3.getContainer().getReadChannel().getIPCPort()));
        assertEquals(ports.iterator().next().intValue(), conf.getInt(OzoneConfigKeys.DFS_CONTAINER_IPC_PORT, OzoneConfigKeys.DFS_CONTAINER_IPC_PORT_DEFAULT));
    }
}

/**
 * Test that a DN can register with SCM even if it was started before the SCM.
 * @throws Exception
 */
@Test
@Timeout(100)
@Flaky("HDDS-6111")
public void testDNstartAfterSCM() throws Exception {
    // Start a cluster with 3 DN
    cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(3).build();
    cluster.waitForClusterToBeReady();
    // Stop the SCM
    StorageContainerManager scm = cluster.getStorageContainerManager();
    scm.stop();
    // Restart DN
    cluster.restartHddsDatanode(0, false);
    // DN should be in GETVERSION state till the SCM is restarted.
    // Check DN endpoint state for 20 seconds
    DatanodeStateMachine dnStateMachine = cluster.getHddsDatanodes().get(0).getDatanodeStateMachine();
    for (int i = 0; i < 20; i++) {
        for (EndpointStateMachine endpoint : dnStateMachine.getConnectionManager().getValues()) {
            Assert.assertEquals(EndpointStateMachine.EndPointStates.GETVERSION, endpoint.getState());
        }
        Thread.sleep(1000);
    }
    // DN should successfully register with the SCM after SCM is restarted.
    // Restart the SCM
    cluster.restartStorageContainerManager(true);
    // Wait for DN to register
    cluster.waitForClusterToBeReady();
    // DN should be in HEARTBEAT state after registering with the SCM
    for (EndpointStateMachine endpoint : dnStateMachine.getConnectionManager().getValues()) {
        Assert.assertEquals(EndpointStateMachine.EndPointStates.HEARTBEAT, endpoint.getState());
    }
}

