@Test
public void testLoadSnapshotInfoOnStart() throws Exception {
    // Stop the Ratis server and manually update the snapshotInfo.
    omRatisServer.getOmStateMachine().loadSnapshotInfoFromDB();
    omRatisServer.stop();
    SnapshotInfo snapshotInfo = omRatisServer.getOmStateMachine().getLatestSnapshot();
    TermIndex newSnapshotIndex = TermIndex.valueOf(snapshotInfo.getTerm(), snapshotInfo.getIndex() + 100);
    omMetadataManager.getTransactionInfoTable().put(TRANSACTION_INFO_KEY, new TransactionInfo.Builder().setCurrentTerm(snapshotInfo.getTerm()).setTransactionIndex(snapshotInfo.getIndex() + 100).build());
    // Start new Ratis server. It should pick up and load the new SnapshotInfo
    omRatisServer = OzoneManagerRatisServer.newOMRatisServer(conf, ozoneManager, omNodeDetails, Collections.emptyMap(), secConfig, certClient, false);
    omRatisServer.start();
    TermIndex lastAppliedTermIndex = omRatisServer.getLastAppliedTermIndex();
    Assert.assertEquals(newSnapshotIndex.getIndex(), lastAppliedTermIndex.getIndex());
    Assert.assertEquals(newSnapshotIndex.getTerm(), lastAppliedTermIndex.getTerm());
}

