    keyName = "../../b/c";
    checkNotAValidPath(keyName);
    keyName = "../../b/c/";
    checkNotAValidPath(keyName);
    keyName = "../../b:/c/";
    checkNotAValidPath(keyName);
    keyName = ":/c/";
    checkNotAValidPath(keyName);
    keyName = "";
    checkNotAValidPath(keyName);
    keyName = "../a/b";
    checkNotAValidPath(keyName);
