@Test
public void testPreExecuteWithNonNullToken() throws Exception {
    /* Let token of ozoneManager.getDelegationToken() is nonNull. */
    when(ozoneManager.getDelegationToken(tester)).thenReturn(token);
    long tokenRenewInterval = 1000L;
    when(ozoneManager.getDelegationTokenMgr().getTokenRenewInterval()).thenReturn(tokenRenewInterval);
    modifiedRequest = omGetDelegationTokenRequest.preExecute(ozoneManager);
    verifyUnchangedRequest();
    long originalInterval = originalRequest.getUpdateGetDelegationTokenRequest().getTokenRenewInterval();
    long renewInterval = modifiedRequest.getUpdateGetDelegationTokenRequest().getTokenRenewInterval();
    Assert.assertNotEquals(originalInterval, renewInterval);
    Assert.assertEquals(tokenRenewInterval, renewInterval);
    /* In preExecute(), if the token is nonNull
     we set GetDelegationTokenResponse with response. */
    Assert.assertNotEquals(CHECK_RESPONSE, modifiedRequest.getUpdateGetDelegationTokenRequest().getGetDelegationTokenResponse().toString());
    Assert.assertNotNull(modifiedRequest.getUpdateGetDelegationTokenRequest().getGetDelegationTokenResponse());
}

