/**
 * Validates instantiation of each OMKeyRequest present inside the
 * (CmdType + BucketLayout) -> RequestClass Mapping.
 */
@Test
public void testGetRequestInstanceFromMap() {
    // Lists to count the number of times each OMKeyRequest is instantiated.
    List<OMKeyRequest> omKeyReqsFSO = new ArrayList<>();
    List<OMKeyRequest> omKeyReqsLegacy = new ArrayList<>();
    List<OMKeyRequest> omKeyReqsOBS = new ArrayList<>();
    // Iterate over each OMKeyRequest present in the mapping.
    OM_KEY_REQUEST_CLASSES.forEach((k, v) -> {
        // Check if this key is associated with an FSO class.
        if (k.contains(BucketLayout.FILE_SYSTEM_OPTIMIZED.toString())) {
            try {
                // Get the declared constructor.
                OMKeyRequest omKeyRequest = getRequestInstanceFromMap(getDummyOMRequest(), k, BucketLayout.FILE_SYSTEM_OPTIMIZED);
                Assert.assertEquals(BucketLayout.FILE_SYSTEM_OPTIMIZED, omKeyRequest.getBucketLayout());
                omKeyReqsFSO.add(omKeyRequest);
            } catch (NoSuchMethodException e) {
                fail("No valid constructor found for " + k);
                e.printStackTrace();
            } catch (InvocationTargetException | InstantiationException | IllegalAccessException e) {
                fail("Exception while creating instance of " + k);
                e.printStackTrace();
            }
        } else {
            // This is a LEGACY / OBS Request class.
            try {
                OMKeyRequest omKeyRequest1 = getRequestInstanceFromMap(getDummyOMRequest(), k, BucketLayout.LEGACY);
                Assert.assertEquals(BucketLayout.LEGACY, omKeyRequest1.getBucketLayout());
                omKeyReqsLegacy.add(omKeyRequest1);
                OMKeyRequest omKeyRequest2 = getRequestInstanceFromMap(getDummyOMRequest(), k, BucketLayout.OBJECT_STORE);
                Assert.assertEquals(BucketLayout.OBJECT_STORE, omKeyRequest2.getBucketLayout());
                omKeyReqsOBS.add(omKeyRequest2);
            } catch (NoSuchMethodException e) {
                fail("No valid constructor found for " + k);
                e.printStackTrace();
            } catch (InvocationTargetException | InstantiationException | IllegalAccessException e) {
                fail("Exception while creating instance of " + k);
                e.printStackTrace();
            }
        }
        LOG.info("Validated request class instantiation for cmdType " + k);
    });
    Assert.assertEquals(12, omKeyReqsFSO.size());
    Assert.assertEquals(13, omKeyReqsLegacy.size());
    Assert.assertEquals(13, omKeyReqsOBS.size());
    // Check if the number of instantiated OMKeyRequest classes is equal to
    // the number of keys in the mapping.
    Assert.assertEquals(OM_KEY_REQUEST_CLASSES.size(), omKeyReqsFSO.size() + omKeyReqsOBS.size());
}

/**
 * Tests behaviour with invalid OMKeyRequest classes.
 *
 * @throws InvocationTargetException if the constructor throws an exception.
 * @throws InstantiationException    if the class is abstract.
 * @throws IllegalAccessException    if the constructor is not accessible.
 */
@Test
public void testAddInvalidRequestClass() throws InvocationTargetException, InstantiationException, IllegalAccessException {
    // Add an OMKeyRequest class that does not have a constructor compatible
    // with the Factory class.
    addRequestClass(Type.PurgePaths, OMPathsPurgeRequestWithFSO.class, BucketLayout.FILE_SYSTEM_OPTIMIZED);
    try {
        // This should fail, since this class does not have a valid constructor -
        // one that takes an OMRequest and a BucketLayout as parameters.
        getRequestInstanceFromMap(OMRequest.newBuilder().setCmdType(Type.PurgeKeys).setClientId("xyz").build(), getKey(Type.PurgePaths, BucketLayout.FILE_SYSTEM_OPTIMIZED), BucketLayout.FILE_SYSTEM_OPTIMIZED);
        fail("No exception thrown for invalid OMKeyRequest class");
    } catch (NoSuchMethodException ex) {
        // expected exception.
        LOG.info("Expected exception thrown for invalid OMKeyRequest class", ex);
    }
}

@Test
public void testNormalizePathsEnabled() throws Exception {
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "/a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "////a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "////a/b/////c/d"));
    Assert.assertEquals("a/b/c/...../d", validateAndNormalizeKey(true, "////a/b/////c/...../d"));
    Assert.assertEquals("a/b/d", validateAndNormalizeKey(true, "/a/b/c/../d"));
    Assert.assertEquals("a", validateAndNormalizeKey(true, "a"));
    Assert.assertEquals("a/b", validateAndNormalizeKey(true, "/a/./b"));
    Assert.assertEquals("a/b", validateAndNormalizeKey(true, ".//a/./b"));
    Assert.assertEquals("a/", validateAndNormalizeKey(true, "/a/."));
    Assert.assertEquals("b/c", validateAndNormalizeKey(true, "//./b/c/"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "a/b/c/d/"));
    Assert.assertEquals("a/b/c/...../d", validateAndNormalizeKey(true, "////a/b/////c/...../d/"));
}

