@Test
public void testUserInfo() throws Exception {
    String bucketName = UUID.randomUUID().toString();
    String volumeName = UUID.randomUUID().toString();
    OzoneManagerProtocolProtos.OMRequest omRequest = OMRequestTestUtils.createBucketRequest(bucketName, volumeName, true, OzoneManagerProtocolProtos.StorageTypeProto.DISK);
    OMBucketCreateRequest omBucketCreateRequest = new OMBucketCreateRequest(omRequest);
    Assert.assertFalse(omRequest.hasUserInfo());
    OzoneManagerProtocolProtos.OMRequest modifiedRequest = omBucketCreateRequest.preExecute(ozoneManager);
    Assert.assertTrue(modifiedRequest.hasUserInfo());
    // Now pass modified request to OMBucketCreateRequest and check ugi and
    // remote Address.
    omBucketCreateRequest = new OMBucketCreateRequest(modifiedRequest);
    InetAddress remoteAddress = omBucketCreateRequest.getRemoteAddress();
    UserGroupInformation ugi = omBucketCreateRequest.createUGI();
    String hostName = omBucketCreateRequest.getHostName();
    // Now check we have original user info, remote address and hostname or not.
    // Here from OMRequest user info, converted to UGI, InetAddress and String.
    Assert.assertEquals(inetAddress.getHostAddress(), remoteAddress.getHostAddress());
    Assert.assertEquals(userGroupInformation.getUserName(), ugi.getUserName());
    Assert.assertEquals(inetAddress.getHostName(), hostName);
}

