            // This part adds 49 buckets.
            volumeABucketsPrefixWithOzoneOwner.add(prefixBucketNameWithOzoneOwner + i);
            addBucketsToCache(volumeName1, prefixBucketNameWithOzoneOwner + i);
        } else {
            volumeABucketsPrefixWithHadoopOwner.add(prefixBucketNameWithHadoopOwner + i);
            addBucketsToCache(volumeName1, prefixBucketNameWithHadoopOwner + i);
        }
    }
    String volumeName2 = "volumeB";
