        Assert.assertTrue(omBucketInfo.getBucketName().startsWith(prefixBucketNameWithOzoneOwner));
        Assert.assertFalse(omBucketInfo.getBucketName().equals(prefixBucketNameWithOzoneOwner + 10));
    }
    omBucketInfoList = omMetadataManager.listBuckets(volumeName2, null, prefixBucketNameWithHadoopOwner, 100);
    // Cause adding a exact name in prefixBucketNameWithOzoneOwner
    // and another 49 buckets, so if we list buckets with --prefix
    // prefixBucketNameWithOzoneOwner, we should get 50 buckets.
    Assert.assertEquals(omBucketInfoList.size(), 50);
    for (OmBucketInfo omBucketInfo : omBucketInfoList) {
        Assert.assertTrue(omBucketInfo.getBucketName().startsWith(prefixBucketNameWithHadoopOwner));
