    //3rd time
    getBucketResponse = (ListObjectResponse) getBucket.get("b1", null, null, null, maxKeys, "", continueToken, null, null, null, null).getEntity();
    Assert.assertFalse(getBucketResponse.isTruncated());
    Assert.assertEquals(1, getBucketResponse.getContents().size());
